function gameplayInputEnabled(): boolean {
  return gameStarted && player.alive && matchState.phase === 'active' && menu.classList.contains('hidden') && !isTextChatTyping()
    && !(network.role === 'client' && awaitingCanonicalGuestAuthority)
    && !pendingClientWorldRepair();
}

function playerSimulationEnabled(): boolean {
  return gameStarted && player.alive && matchState.phase !== 'ended' && menu.classList.contains('hidden')
    && !localKillstreakActorSnapshot()?.possession
    && !(network.role === 'client' && awaitingCanonicalGuestAuthority)
    && !pendingClientWorldRepair();
}

function resetLocalSpinUp(): void {
  spinUpWeapon = null;
  spinUpStartedAtPerformanceMs = null;
  spinUpStartedAtHostTimeMs = null;
}

function sendLocalTriggerEdge(pressed: boolean, weapon: WeaponId): void {
  if (network.role !== 'client') return;
  const message: TriggerStateMessage = {
    type: 'trigger-state',
    protocolVersion: MULTIPLAYER_PROTOCOL_VERSION,
    by: player.id,
    connectionEpoch: localConnectionEpoch,
    lifeId: localContinuity,
    actionSequence: localTriggerActionSequence,
    weapon,
    pressed,
    nonce: randomNonce(),
  };
  localTriggerActionSequence += 1;
  network.send(message);
}

function syncLocalTriggerAuthority(held: boolean): void {
  if (network.role !== 'client') {
    transmittedTriggerHeld = false;
    transmittedTriggerWeapon = null;
    return;
  }
  if (awaitingCanonicalGuestAuthority || pendingClientWorldRepair()) {
    transmittedTriggerHeld = false;
    transmittedTriggerWeapon = null;
    return;
  }
  const weaponChanged = transmittedTriggerHeld && transmittedTriggerWeapon !== player.weapon;
  if (transmittedTriggerHeld && (!held || weaponChanged) && transmittedTriggerWeapon) {
    sendLocalTriggerEdge(false, transmittedTriggerWeapon);
    transmittedTriggerHeld = false;
    transmittedTriggerWeapon = null;
  }
  if (!held || !gameStarted || !player.alive || matchState.phase !== 'active') return;
  if (!transmittedTriggerHeld) {
    // The reliable state commit and following edge share the ordered event lane,
    // so the host admits the current weapon/life before starting its hold clock.
    network.sendStateCommitReliably(createStateMessage());
    sendLocalTriggerEdge(true, player.weapon);
    transmittedTriggerHeld = true;
    transmittedTriggerWeapon = player.weapon;
  }
}

function setLocalTriggerHeld(held: boolean): void {
  triggerHeld = held;
  syncLocalTriggerAuthority(held);
  if (!held) resetLocalSpinUp();
}

function sendLocalReloadCancel(): void {
  clearExpiredLocalReloadAuthority();
  const pending = pendingLocalReloadAuthority;
  if (network.role !== 'client' || !pending
    || applyingLocalReloadAuthority || awaitingCanonicalGuestAuthority || pendingClientWorldRepair()) return;
  const actionSequence = localReloadActionSequence.next();
  const cancelling = cancelRequested(pending, actionSequence);
  if (!cancelling) return;
  pendingLocalReloadAuthority = cancelling;
  const message: ReloadIntentMessage = {
    type: 'reload-intent', protocolVersion: MULTIPLAYER_PROTOCOL_VERSION,
    by: player.id, connectionEpoch: localConnectionEpoch, lifeId: localContinuity,
    actionSequence, weapon: pending.weapon, action: 'cancel', nonce: randomNonce(),
  };
  network.send(message);
}

function interruptReload(force = false, now = performance.now()): void {
  if (!player.reloadState) {
    if (force) sendLocalReloadCancel();
    weaponView.cancelReload();
    return;
  }
  if (force || cancelReload(player.reloadState, now)) {
    sendLocalReloadCancel();
    player.reloadState = null;
    weaponView.cancelReload();
  }
}

function clearGameplayInput(): void {
  cancelFInteractionPress('manual-reset');
  releaseCareCapture();
  interruptReload(false);
  keys.clear();
  gamepadMove = { x: 0, y: 0 };
  gamepadLookRate = { yaw: 0, pitch: 0 };
  gamepadDroneVertical = 0;
  gamepadSprint = false;
  mouseTriggerHeld = false;
  mouseAdsHeld = false;
  setLocalTriggerHeld(false);
  // A focus/pointer/menu reset is a real ADS release. Route it through the
  // Railgun's post-shot latch so the next trusted RMB press can reveal again;
  // directly assigning false left the latch permanently armed after a shot.
  adsHeld = admittedAdsHeld(false);
  sniperScopeActive = false;
  dmrThermalActive = false;
  sniperScopeOverlay.hidden = true;
  hudRoot.classList.remove('sniper-scope-active');
  applyCompactOpticSightPicture(hudRoot, deriveCompactOpticSightPicture({
    alive: false, weapon: player.weapon, adsHeld: false, adsProgress: 0,
    baseFovDegrees: preferredFov, cameraFovDegrees: camera.fov,
  }));
  dmrThermalPresentation.update(camera, [], false);
  hudRoot.classList.remove('dmr-thermal-active');
  deactivateRailgunScopePresentation();
  audio.minigunDrive(0, 'idle', false);
  currentSprinting = false;
  jumpQueuedAt = -10_000;
  player.velocity.x = 0;
  player.velocity.z = 0;
}

function setStatus(text: string, kind: 'ok' | 'warn' | 'error' = 'ok'): void {
  statusEl.textContent = text;
  statusEl.dataset.kind = kind;
  if (menuLifecycle.surface === 'deploying') {
    deploymentTransitionStatus.textContent = text;
    deploymentTransition.dataset.statusKind = kind;
  }
}

/**
 * HF-325 Part 1: a guest whose host dies used to grind silently through the 90s
 * retry and a guest of a reset room retried a room id that will never exist
 * again. network.ts already samples the raw link state; this turns that sample
 * into something the player actually sees.
 *
 * Read-only presentation. It never promotes, never adopts authority and never
 * writes a position, health, ammo, admission or match-start value — Part 2 of
 * the handoff stays disabled.
 */
let lastHostLossState: HostLossState = 'inactive';
let lastHostLossCountdownSeconds = -1;
// QA diagnostics for the succession wire (read-only, surfaced through
// __ATOMIC_ACRES_DEBUG__.sampleHostSuccession). A silent refusal anywhere in
// the mint/ship/accept chain otherwise looks identical to "not wired".
let lastSuccessionPublish: { reason: string; sent: boolean; rosterRevision: number } | null = null;
let lastMirrorShip: { reason: string } | null = null;
let lastMandateAccept: { accepted: boolean; reason: string } | null = null;
let lastMirrorAccept: { accepted: boolean; reason: string } | null = null;

/**
 * HF-325: adopt the mirrored checkpoint through the EXISTING host recovery
 * path (initializeRecoveredHostLobby → resumeRecoveredHostMatch →
 * restoreGuestAuthorities / restoreRailgunAuthority /
 * restoreTimedMapWeaponAuthorities / resolveHostMatchResumeTiming). That path
 * is already tested against downtime; the arrival-time clock rebase is what
 * makes its Date.now() arithmetic honest on this second machine. Never a
 * bespoke adoption routine.
 */
function adoptMirroredHostAuthority(checkpoint: HostMatchCheckpoint): void {
  if (network.role !== 'host' || checkpoint.roomCode !== network.roomCode) return;
  if (!initializeRecoveredHostLobby(checkpoint)) {
    // Fail closed: a promoted host that cannot adopt the ledger owns nothing.
    setStatus('Promoted, but the mirrored match state could not be adopted. Room closed.', 'error');
    network.announceLobbyClosed('host-superseded');
    network.close();
  }
}

/**
 * HF-325 G4, host half: a higher succession term exists, so this host has been
 * superseded. Stop broadcasting authority (the publisher is already stood
 * down), farewell whatever guests are still attached so they stop rejoining a
 * dead room, surrender the room, and tell the player.
 */
function standDownAsSupersededHost(observedTerm: number): void {
  network.announceLobbyClosed('host-superseded');
  network.close();
  invalidateMatchAdmission(`Superseded by host succession term ${observedTerm}`);
  setStatus('A newer host owns this match — this room has been closed.', 'error');
  addFeed('HOST SUPERSEDED — ROOM CLOSED', 'coral');
}

function updateHostLossPresentation(nowMonoMs: number): void {
  const assessment = evaluateHostLoss(network.hostLinkSample(nowMonoMs));
  // HF-325: the self-promotion trigger. Every guard — confirmed host loss,
  // host-issued mandate naming this peer, term fence, roster re-election,
  // survivor floor, mirror freshness — lives in evaluateSelfPromotion and
  // authorizeSelfPromotion. The room-id claim in promoteToHost is the
  // mutual-exclusion lock: if anything else owns the id, the claim aborts
  // permanently and this peer goes offline instead of racing a live host.
  if (assessment.state === 'host-lost' && network.role === 'client' && network.roomCode) {
    const roster = successionRoster();
    if (roster) {
      const decision = evaluateSelfPromotion(successorHoldings, {
        selfId: player.id,
        roomCode: network.roomCode,
        assessment,
        roster,
        nowEpochMs: Date.now(),
      });
      if (decision.promote) {
        network.promoteToHost(decision.roomCode, () => {
          const claim = buildHostPromotedMessage(decision, randomNonce());
          if (claim) network.send(claim);
          adoptMirroredHostAuthority(decision.checkpoint);
        });
      }
    }
  }
  const presentation = hostLossPresentation(assessment);
  const countdownSeconds = assessment.remainingMs === null
    ? -1
    : Math.max(0, Math.ceil(assessment.remainingMs / 1_000));
  const stateChanged = assessment.state !== lastHostLossState;
  // 'reconnecting' carries a live whole-second countdown in its detail line;
  // refresh on the second boundary only so the status element is not rewritten
  // every frame.
  const countdownChanged = !stateChanged
    && assessment.state === 'reconnecting'
    && countdownSeconds !== lastHostLossCountdownSeconds;
  if (!stateChanged && !countdownChanged) return;
  const previousState = lastHostLossState;
  lastHostLossState = assessment.state;
  lastHostLossCountdownSeconds = countdownSeconds;
  if (presentation.visible) {
    setStatus(`${presentation.headline} — ${presentation.detail}`, presentation.tone);
    if (stateChanged) addFeed(presentation.headline, presentation.tone === 'error' ? 'coral' : 'gold');
    return;
  }
  // Only report recovery when something was previously being reported, so this
  // never overwrites an unrelated lobby status line.
  if (previousState === 'unstable' || previousState === 'reconnecting') {
    setStatus('Host connection restored.', 'ok');
    addFeed('HOST CONNECTION RESTORED', 'aqua');
  }
}

function selectLobbyCodeForManualCopy(code: string): void {
  const range = document.createRange();
  range.selectNodeContents(roomCodeEl);
  const selection = window.getSelection();
  selection?.removeAllRanges();
  selection?.addRange(range);
  element<HTMLInputElement>('#room-input').value = code;
}

function currentMatchRules() {
  // MAP3 (HF-409 finisher 2): an EXPLORE arena has no clock and no score
  // limit, so nothing can run out and nobody can win. The registry row keeps
  // `matchRules.durationMs` because the arena id is also the replay/storage
  // boundary and a saved match naming map3 must still decode - the RUNTIME
  // rules are what the match state machine reads, and they follow the KIND.
  // Without this, walking the showcase ends in a VICTORY/DEFEAT card at five
  // minutes, which is the same lie as the TEAM DEATHMATCH banner.
  if (selectedArena.kind === 'explore') return EXPLORE_MATCH_RULES;
  if (gameMode === 'solo') return selectedArena.matchRules;
  // HF-377: the lobby config is the replicated match contract; its kill limit
  // applies identically to TDM (squad score) and FFA (leader kills) because
  // both advanceMatch and advanceFreeForAllMatch consume MatchRules.scoreLimit.
  const config = privateLobbySnapshot?.config ?? privateMatchConfig;
  return { durationMs: config.durationMs, scoreLimit: config.scoreLimit };
}

function areCombatantsHostile(aId: string, aTeam: Team, bId: string, bTeam: Team): boolean {
  if (gameMode === 'solo') return aTeam !== bTeam;
  return playersAreHostile(privateMatchMode, { id: aId, team: aTeam }, { id: bId, team: bTeam });
}

function renderHighScores(): void {
  const list = element<HTMLOListElement>('#high-score-list');
  const card = element<HTMLElement>('#high-score-card');
  const currentName = normalizeRequiredPlayerName(element<HTMLInputElement>('#player-name').value) ?? storedPlayerName;
  if (selectedArena.id === 'gun-range') {
    card.dataset.board = 'gun-range';
    element<HTMLElement>('#global-leaderboard-status').textContent = 'LOCAL RANGE RECORDS';
    element<HTMLElement>('#high-score-title').textContent = 'GUN RANGE LEADERBOARD';
    element<HTMLElement>('#high-score-footnote').textContent = 'Timed 2-minute rounds · ranked by score, then accuracy · local to this browser.';
    if (gunRangeScores.length === 0) {
      list.innerHTML = '<li class="empty">Run a 2-minute score attack to set the first range record.</li>';
    } else {
      list.innerHTML = gunRangeScores.slice(0, 8).map((entry, index) => (
        `<li><b>${index + 1}</b><strong>${escapeHtml(entry.name)}</strong><span>${entry.score.toLocaleString()} PTS</span><small>${entry.hits} HITS · ${entry.accuracy}% ACC · ${entry.shots} SHOTS</small></li>`
      )).join('');
    }
    const best = personalBestGunRange(gunRangeScores, currentName);
    element<HTMLElement>('#personal-best').textContent = best
      ? `YOUR BEST ${best.score.toLocaleString()} · ${best.accuracy}% ACC`
      : 'NO RANGE PERSONAL BEST';
    return;
  }
  card.dataset.board = 'streak';
  element<HTMLElement>('#high-score-title').textContent = 'NUKE TOWN LEADERBOARD';
  element<HTMLElement>('#high-score-footnote').textContent = pass65Settings.privacy.shareGlobalLeaderboard
    ? 'Global result sharing is enabled · local cache remains available offline.'
    : 'Public records are readable · sharing your results is off by default in Options.';
  if (highScores.length === 0) {
    list.innerHTML = '<li class="empty">Set the first named streak record.</li>';
  } else {
    list.innerHTML = highScores.slice(0, 8).map((entry, index) => (
      `<li><b>${index + 1}</b><strong>${escapeHtml(entry.name)}</strong><span>×${entry.bestStreak} STREAK</span><small>${entry.kills} KILLS · ${entry.deaths}D${entry.won ? ' · WIN' : ''}</small></li>`
    )).join('');
  }
  const best = personalBest(highScores, currentName);
  element<HTMLElement>('#personal-best').textContent = best
    ? `YOUR BEST ×${best.bestStreak} · ${best.kills} KILLS`
    : 'NO PERSONAL BEST';
  element<HTMLElement>('#global-leaderboard-status').textContent = globalLeaderboardState === 'live'
    ? 'GLOBAL STREAK RECORDS · LIVE'
    : globalLeaderboardState === 'saved'
      ? 'GLOBAL STREAK RECORDS · SAVED'
      : globalLeaderboardState === 'pending'
        ? 'GLOBAL STREAK RECORDS · CONNECTING'
        : 'GLOBAL STREAK RECORDS · OFFLINE CACHE';
}

function persistMergedGunRangeScores(incoming: readonly unknown[]): void {
  gunRangeScores = mergeGunRangeScores(gunRangeScores, incoming);
  try {
    saveGunRangeScores(localStorage, gunRangeScores);
  } catch {
    /* optional */
  }
  renderHighScores();
}

function recordGunRangeRound(): void {
  if (!isGunRange(selectedArena.id)) return;
  const recordedAt = Date.now();
  const entry = createGunRangeScoreEntry(player.name, rangeScore, targetHits, rangeShotsFired, recordedAt);
  if (!entry) return;
  persistMergedGunRangeScores([entry]);
  addFeed(`RANGE ROUND · ${entry.score.toLocaleString()} PTS · ${entry.hits} HITS · ${entry.accuracy}% ACC`, 'gold');
}

function persistMergedHighScores(incoming: readonly unknown[], notifyTabs = true): void {
  highScores = mergeHighScores(highScores, incoming);
  try {
    saveHighScores(localStorage, highScores);
  } catch {
    setStatus('Records cannot persist in this browser context.', 'warn');
  }
  renderHighScores();
  if (notifyTabs) highScoreChannel?.postMessage(highScores);
}

function sendLeaderboardSync(): void {
  if (network.role !== 'offline') network.send({ type: 'leaderboard-sync', by: player.id, season: LEADERBOARD_SEASON, entries: highScores });
}

async function refreshGlobalLeaderboard(): Promise<void> {
  if (!GLOBAL_LEADERBOARD_ENDPOINT || !externalLeaderboardNetworkEnabled) {
    globalLeaderboardState = 'cached';
    renderHighScores();
    return;
  }
  globalLeaderboardState = 'pending';
  renderHighScores();
  try {
    const entries = await fetchGlobalLeaderboard();
    persistMergedHighScores(entries);
    globalLeaderboardState = 'live';
  } catch {
    globalLeaderboardState = 'cached';
  }
  renderHighScores();
}

function recordImmediateStreak(syncGlobal = true): void {
  const fieldSupport = localFieldSupportProjection();
  const existing = personalBest(highScores, player.name);
  if (existing && existing.bestStreak >= fieldSupport.streak) return;
  const entry = immediateStreakEntry(
    player.name,
    fieldSupport.streak,
    player.kills,
    player.deaths,
  );
  if (!entry) return;
  persistMergedHighScores([entry]);
  if (network.role !== 'offline') network.send({ type: 'high-score', by: player.id, season: LEADERBOARD_SEASON, entry });
  if (!syncGlobal || !externalLeaderboardNetworkEnabled || !pass65Settings.privacy.shareGlobalLeaderboard) return;
  const leaderboardInstallation = leaderboardInstallId(localStorage, true);
  if (!leaderboardInstallation) return;
  const nameKey = entry.id.replace(/^global:/, '');
  void submitGlobalStreak({
    name: entry.name,
    streak: entry.bestStreak,
    kills: entry.kills,
    deaths: entry.deaths,
    installId: leaderboardInstallation,
    buildId: LEADERBOARD_BUILD_ID,
    idempotencyKey: `${leaderboardInstallation}:${nameKey}:${entry.bestStreak}`.slice(0, 120),
    season: LEADERBOARD_SEASON,
  }, pass65Settings.privacy.shareGlobalLeaderboard).then((accepted) => {
    globalLeaderboardState = accepted ? 'saved' : 'cached';
    renderHighScores();
  }).catch(() => {
    globalLeaderboardState = 'cached';
    renderHighScores();
  });
}

function recordCompletedMatch(): void {
  if (matchScoreRecorded || matchState.phase !== 'ended') return;
  matchScoreRecorded = true;
  if (isGunRange(selectedArena.id)) {
    recordGunRangeRound();
    return;
  }
  const recordedAt = Date.now();
  const authoritativeLocal = gameMode === 'solo' ? null : authoritativeScores.get(player.id) ?? null;
  const entry: HighScoreEntry = {
    id: `score:${player.id}:${recordedAt.toString(36)}`,
    name: player.name,
    kills: Math.min(MAX_MATCH_KILLS, Math.max(0, Math.floor(authoritativeLocal?.kills ?? player.kills))),
    deaths: Math.min(200, Math.max(0, Math.floor(authoritativeLocal?.deaths ?? player.deaths))),
    bestStreak: Math.min(MAX_MATCH_KILLS, Math.max(0, Math.floor(bestStreakThisMatch))),
    won: gameMode !== 'solo' && privateMatchMode === 'ffa'
      ? matchState.winnerPlayerId === player.id
      : matchState.winner === player.team,
    recordedAt,
  };
  persistMergedHighScores([entry]);
  if (network.role !== 'offline') network.send({ type: 'high-score', by: player.id, season: LEADERBOARD_SEASON, entry });
}

function requirePlayerName(): string | null {
  const input = element<HTMLInputElement>('#player-name');
  const error = element<HTMLElement>('#player-name-error');
  const name = normalizeRequiredPlayerName(input.value);
  input.classList.toggle('invalid', !name);
  error.hidden = Boolean(name);
  if (!name) {
    setStatus('Enter a callsign before deployment.', 'error');
    input.focus();
    return null;
  }
  input.value = name;
  player.name = name;
  storedPlayerName = name;
  try { localStorage.setItem(PLAYER_NAME_STORAGE_KEY, name); } catch { /* Match start does not depend on storage access. */ }
  renderHighScores();
  return name;
}

/**
 * Last-resort fatal message. A hoisted function declaration that touches
 * NOTHING but `document`, so it works at any point in module evaluation -
 * including before every module-scope binding below it exists. This is the
 * floor under showFatalError: whatever else fails, the player is told why.
 */
function renderPreInitFatalMessage(message: string): void {
  if (typeof document === 'undefined' || !document.body) return;
  const existing = document.getElementById('pre-init-fatal');
  const node = existing ?? document.createElement('div');
  node.id = 'pre-init-fatal';
  node.setAttribute('role', 'alert');
  node.style.cssText = 'position:fixed;inset:0;z-index:2147483647;display:flex;'
    + 'align-items:center;justify-content:center;padding:8vh 6vw;margin:0;'
    + 'background:#140f0c;color:#f4ece2;font:600 clamp(15px,2.2vw,22px)/1.5 '
    + 'ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;text-align:center;'
    + 'white-space:pre-wrap;';
  node.textContent = message;
  if (!existing) document.body.appendChild(node);
}

function showFatalError(error: unknown): void {
  const message = error instanceof Error ? error.message : String(error);
  // Console FIRST, because it depends on nothing. Everything below this line
  // touches module-scope state that may not exist yet.
  console.error('[Nuke Town fatal]', error);
  // Owner-facing correctness. showFatalError is reachable DURING module
  // evaluation - the WebGPU requirement path calls it from the top-level
  // bootstrap at ~line 1854, which runs BEFORE `bootstrapStage` (~2339),
  // `clientWorldRepairAdmission` (~5638) and every other binding used here.
  // Reading or assigning a module `let` from inside its temporal dead zone
  // throws a ReferenceError, so the error reporter destroyed the very message
  // it existed to deliver, in the one situation where a clear message matters
  // most: a browser that cannot run the game at all.
  //
  // A previous fix (1a263aa0) guarded only `clientWorldRepairAdmission` and so
  // fixed the INSTANCE, not the CLASS - `setBootstrapStage('failed')` on the
  // very next line hit the same dead zone, and the cross-browser gate caught
  // "Cannot access 'bootstrapStage' before initialization" still reaching the
  // player. The whole tail is therefore one guarded block: this function's
  // contract is that it works at ANY point in the lifecycle, and ordering is
  // not something a 34k-line module can be trusted to preserve. Not throwing
  // is. See src/regression-fatal-error-preinit.test.ts, which now pins the
  // class rather than either instance.
  try {
    clientWorldRepairAdmission = null;
    pendingClientReconnectWorldRepairConnectionEpoch = null;
    setBootstrapStage('failed');
    bootstrapError = message;
    gameStarted = false;
    // Silence the music with the match. A failed bootstrap leaves the player on
    // an error screen, and a cheerful loop under a failure message reads as a
    // bug.
    audio.stopGameMusic();
    clearGameplayInput();
    setLocalTriggerHeld(false);
    setStatus(`Game paused: ${message}`, 'error');
    applyMenuLifecycle({ type: 'fatal-error' });
    presentBanner('fatal', 'SYSTEM PAUSED', 'Reload the page to re-enter the test block.', null);
  } catch {
    // Pre-initialisation call: none of the state above exists yet, and the
    // usual UI cannot be reached. Fall back to a primitive DOM write so the
    // real message still lands on screen.
    renderPreInitFatalMessage(message);
  }
}

const webRtcSupported = typeof window.RTCPeerConnection === 'function';
if (!webRtcSupported) {
  element<HTMLButtonElement>('#host').disabled = true;
  element<HTMLButtonElement>('#join').disabled = true;
  setStatus('This browser lacks WebRTC; solo training is still available.', 'warn');
} else if (typeof canvas.requestPointerLock !== 'function') {
  setStatus('Pointer lock is unavailable; keyboard movement works but mouse aim may not.', 'warn');
}

// HF-339: centre-banner ownership. See banner-arbiter.ts for the ranking.
let centreBannerState: BannerState = createBannerState();
let centreBannerRequestSeq = 0;

function applyCentreBannerTransition(transition: BannerTransition): void {
  centreBannerState = transition.state;
  if (transition.display.kind === 'none') return;
  const banner = element<HTMLElement>('#banner');
  if (transition.display.kind === 'hide') {
    banner.hidden = true;
    return;
  }
  banner.innerHTML = transition.display.html
    ?? `<strong>${transition.display.headline}</strong><span>${transition.display.subline}</span>`;
  banner.hidden = false;
}

/** Composite screens (match end) present raw markup but still take ownership
 * through the arbiter, so no stale lower-rank expiry can hide them. */
function presentBannerHtml(priority: BannerPriority, ownershipHeadline: string, html: string, durationMs: number | null): number {
  const id = ++centreBannerRequestSeq;
  applyCentreBannerTransition(requestBanner(centreBannerState, {
    id, priority, headline: ownershipHeadline, subline: '', durationMs, html,
  }));
  if (durationMs !== null) {
    window.setTimeout(() => applyCentreBannerTransition(expireBanner(centreBannerState, id)), durationMs);
  }
  return id;
}

/** The only sanctioned writer of #banner. Returns the request id. */
function presentBanner(priority: BannerPriority, headline: string, subline: string, durationMs: number | null): number {
  const id = ++centreBannerRequestSeq;
  applyCentreBannerTransition(requestBanner(centreBannerState, { id, priority, headline, subline, durationMs }));
  if (durationMs !== null) {
    window.setTimeout(() => applyCentreBannerTransition(expireBanner(centreBannerState, id)), durationMs);
  }
  return id;
}

function clearCentreBanner(): void {
  applyCentreBannerTransition(clearBanners());
}

function setNetworkStatus(text: string, kind: 'ok' | 'warn' | 'error' = 'ok'): void {
  setStatus(text, kind);
  // ArenaNetwork finalizes an attempt immediately around its status update.
  // Observe it after that synchronous transition so failed attempts become
  // retryable and successful attempts cannot leave stale pending button copy.
  queueMicrotask(() => {
    if (network.role !== 'client' || !network.diagnostics().hostConnectionOpen) {
      clientWorldRepairAdmission = null;
      pendingClientReconnectWorldRepairConnectionEpoch = null;
      clientReconnectWorldRepairAttempts = 0;
      clearClientWorldRepairTimeout();
    }
    const admissionToken = matchAdmissionCoordinator.token();
    if (admissionToken) {
      try {
        assertMatchAdmissionCurrent(admissionToken);
      } catch (error) {
        if (!isMatchAdmissionSuperseded(error)) reportRuntimeError('match-admission-network-authority', error);
        invalidateMatchAdmission('Network role, room or connection authority changed');
      }
    }
    syncArenaSelectionUi();
  });
}

const network = new ArenaNetwork(onNetworkMessage, setNetworkStatus, (entry) => {
  appendClientRuntimeLog(entry, clientPersistentStorage());
});

function pendingClientWorldRepair(): boolean {
  return network.role === 'client' && clientWorldRepairPending(clientWorldRepairAdmission);
}

// Text chat lives in ./text-chat-controller; this seam injects every piece of
// shared mutable state it reads as a live thunk/reference so behaviour stays
// byte-identical with the pre-extraction inline implementation.
const textChatController = createTextChatController({
  elements: { root: textChatRoot, log: textChatLog, hint: textChatHint, input: textChatInput },
  network,
  appRoot: app,
  hudRoot,
  localPlayerId: () => player.id,
  hostId: () => privateLobbySnapshot?.hostId ?? null,
  hasLobby: () => privateLobbySnapshot !== null,
  inGame: () => gameStarted,
  shouldResumeControls: () => gameStarted && player.alive && !matchFinished && menu.classList.contains('hidden'),
  inPointerLock: () => document.pointerLockElement === canvas,
  clearGameplayInput,
  resumePointerLock: () => requestGamePointerLock('chat-close'),
  nonce: randomNonce,
  hostMember: (id) => hostLobbyMembers.get(id),
});

const {
  available: textChatAvailable,
  typing: isTextChatTyping,
  render: renderTextChat,
  markActivity: markTextChatActivity,
  open: openTextChat,
  close: closeTextChat,
  reset: resetTextChat,
  sendHistory: sendTextChatHistory,
  admitHostSubmit: admitHostChatSubmit,
  submit: submitTextChat,
  acceptHostMessage: acceptHostChatMessage,
  acceptHostHistory: acceptHostChatHistory,
  forgetPlayer: forgetTextChatParticipant,
  debugSnapshot: textChatDebugSnapshot,
} = textChatController;

function randomLobbyCredential(): string {
  if (typeof crypto?.randomUUID === 'function') return crypto.randomUUID();
  return `room_${Date.now().toString(36)}_${Math.floor(protocolRandom() * Number.MAX_SAFE_INTEGER).toString(36)}`;
}

const roomIdentityTabId = randomLobbyCredential();
let activeRoomIdentityCode = '';

function saveActiveRoomIdentity(roomCode: string): void {
  saveRoomRejoinIdentity(
    roomCode,
    {
      playerId: player.id,
      token: localResumeToken,
      ...(localHostConfirmedContinuity === null ? {} : { authoritativeLifeId: localHostConfirmedContinuity }),
    },
    sessionStorage,
    localStorage,
    REJOIN_GRACE_MS,
    Date.now(),
    roomIdentityTabId,
  );
  saveLastRoomCode(roomCode, localStorage);
  activeRoomIdentityCode = roomCode;
}

function restoreRoomIdentity(roomCode: string): void {
  let restored: ReturnType<typeof loadRoomRejoinIdentity> = null;
  try {
    restored = loadRoomRejoinIdentity(roomCode, sessionStorage, localStorage, Date.now(), roomIdentityTabId);
  } catch { /* Hardened storage falls back to a fresh identity. */ }
  if (restored) {
    player.id = restored.playerId;
    localResumeToken = restored.token;
    localHostConfirmedContinuity = restored.authoritativeLifeId ?? null;
    // HF-322: Only treat a restored identity as a mid-match resume when the lobby phase actually warrants it
    const isMidMatch = gameStarted || privateLobbySnapshot?.phase === 'active' || privateLobbySnapshot?.phase === 'countdown';
    awaitingAuthoritativeRejoinContinuity = isMidMatch;
    awaitingCanonicalGuestAuthority = isMidMatch;
    pendingGuestResumeAuthority = null;
    try { saveActiveRoomIdentity(roomCode); } catch { /* The in-memory credential remains valid. */ }
    return;
  }
  localHostConfirmedContinuity = null;
  awaitingAuthoritativeRejoinContinuity = false;
  awaitingCanonicalGuestAuthority = false;
  pendingGuestResumeAuthority = null;
  clientReconnectWorldRepairAttempts = 0;
  clearClientWorldRepairTimeout();
  clearGuestResumeTimeout();
  lastGuestResumeNackNonce = null;
  lastAppliedGuestResumeAuthority = null;
  localResumeToken = randomLobbyCredential();
  try {
    saveActiveRoomIdentity(roomCode);
  } catch { /* Rejoin remains available only while this page stays open. */ }
}

function persistRoomIdentityForCloseTabRejoin(): void {
  if (network.role !== 'client' || !network.roomCode || !localResumeToken) return;
  try {
    saveActiveRoomIdentity(network.roomCode);
    releaseRoomRejoinIdentityLease(network.roomCode, localStorage, roomIdentityTabId);
  } catch { /* Browser storage policy can make close-tab recovery unavailable. */ }
}

function hidePrivateLobbyPresentation(): void {
  menu.classList.remove('private-lobby-active');
  element<HTMLElement>('#private-lobby').hidden = true;
}

function resetPrivateLobbyState(): void {
  invalidateMatchAdmission('Private lobby state reset');
  hostLobbySessionGeneration += 1;
  if (activeRoomIdentityCode) {
    try { releaseRoomRejoinIdentityLease(activeRoomIdentityCode, localStorage, roomIdentityTabId); } catch { /* Lease expires if storage is unavailable. */ }
    activeRoomIdentityCode = '';
  }
  if (lobbyClockTimer) clearTimeout(lobbyClockTimer);
  lobbyClockTimer = null;
  privateLobbySnapshot = null;
  privateLobbyRevision = 0;
  hostSuccessionPublisher = createHostSuccessionPublisher(); // HF-325
  successorHoldings = createSuccessorHoldings();             // HF-325
  privateMatchActiveAtHostTimeMs = null;
  privateMatchActiveAtEpochMs = null;
  privateMatchMode = 'ffa';
  privateMatchConfig = DEFAULT_PRIVATE_MATCH_CONFIG;
  hostTimeMapping = createHostTimeMapping();
  interpolationDelayState = createInterpolationDelayState(performance.now());
  lastObservedInterpolationUnderruns = 0;
  localCombatEventSeq = 0;
  peerTimingStates.clear();
  localLobbyPingMs = null;
  localLobbyReady = false;
  localDhv = 10;
  localResumeToken = '';
  clientWorldRepairAdmission = null;
  pendingClientReconnectWorldRepairConnectionEpoch = null;
  clientReconnectWorldRepairAttempts = 0;
  clearClientWorldRepairTimeout();
  hostKillstreakLoadoutAcks.clear();
  localHostConfirmedContinuity = null;
  awaitingAuthoritativeRejoinContinuity = false;
  awaitingCanonicalGuestAuthority = false;
  pendingGuestResumeAuthority = null;
  lastAppliedGuestResumeAuthority = null;
  localConnectionEpoch = randomLobbyCredential();
  localTriggerActionSequence = 0;
  transmittedTriggerHeld = false;
  transmittedTriggerWeapon = null;
  hostTriggerAuthorities.clear('match-reset');
  lobbyArenaSyncPromise = Promise.resolve();
  hostLobbyMembers.clear();
  hostLobbyTokens.clear();
  hostLobbyTokenDigests.clear();
  hostLobbyConnectionEpochs.clear();
  hostDisconnectedAt.clear();
  pendingHostRecoveryJoins.clear();
  hostLobbyAdmissionInFlight.clear();
  pendingGuestAuthorityRepairs.clear();
  hostMatchRecoveryPreparing = false;
  retainedRemoteAuthorities.clear();
  remoteCombatInventories.clear();
  remoteCombatInventoryRevisions.clear();
  for (const timer of remoteReloadTimers.values()) window.clearTimeout(timer);
  remoteReloadTimers.clear();
  remoteReloadAuthorities.clear();
  pendingLocalOrdinaryShots.clear();
  pendingLocalReloadAuthority = null;
  pendingLocalPickup = null;
  localReloadActionSequence.reset();
  lastAppliedLocalCombatAuthorityRevision = -1;
  lastAppliedLocalShotResultSeq = -1;
  authoritativeScores.clear();
  resetTextChat();
  gunRangeMatchClockState = null;
  gunRangeMatchClockOccupantIds = Object.freeze([]);
  gunRangeTestBayDoorState = null;
  presentedGunRangeTestBayDoorThumpSequence = 0;
  gunRangeTestBayDoorBroadcastPending = false;
  hidePrivateLobbyPresentation();
}

function gunRangeMatchClockDurationMs(): number | null {
  const multiplayerConfig = privateLobbySnapshot?.config ?? privateMatchConfig;
  const arenaId = network.role === 'offline' ? selectedArena.id : multiplayerConfig.arenaId;
  return arenaId === 'gun-range' ? GUN_RANGE_ROUND_MS : null;
}

function admittedGunRangeClockParticipants(): readonly GunRangeClockParticipant[] {
  if (network.role === 'client') return Object.freeze([]);
  if (network.role === 'offline') {
    return Object.freeze([Object.freeze({
      id: player.id,
      admitted: true,
      connected: true,
      alive: player.alive,
      position: Object.freeze({ x: player.position.x, y: player.position.y, z: player.position.z }),
    })]);
  }
  const participants: GunRangeClockParticipant[] = [];
  const hostMember = hostLobbyMembers.get(player.id);
  participants.push(Object.freeze({
    id: player.id,
    admitted: hostMember !== undefined,
    connected: hostMember?.connected === true,
    alive: player.alive,
    position: Object.freeze({ x: player.position.x, y: player.position.y, z: player.position.z }),
  }));
  for (const member of hostLobbyMembers.values()) {
    if (member.id === player.id) continue;
    const remote = remotes.get(member.id);
    const retained = retainedRemoteAuthorities.get(member.id)?.snapshot;
    const authoritative = retained ?? remote?.snapshot;
    const health = remoteHealthAuthorities.get(member.id);
    if (!authoritative) continue;
    participants.push(Object.freeze({
      id: member.id,
      admitted: true,
      // Lobby admission alone is not proof that a replacement document has
      // applied its retained pose. The exact resume ACK releases this flag, so
      // a rejoin can pause the shared clock only after canonical restoration.
      connected: member.connected && remote !== undefined && !remote.awaitingReplacementState,
      alive: health?.alive === true,
      position: Object.freeze({ x: authoritative.x, y: authoritative.y, z: authoritative.z }),
    }));
  }
  return Object.freeze(participants);
}

function sampleAuthoritativeGunRangeTestBayDoor(nowHostTimeMs: number): GunRangeTestBayDoorState | null {
  if (selectedArena.id !== 'gun-range' || matchState.phase !== 'active' || network.role === 'client') return null;
  const prior = gunRangeTestBayDoorState ?? createGunRangeTestBayDoorState(nowHostTimeMs);
  // A hidden-tab authority heartbeat samples performance.now(), while a
  // previously queued rAF can subsequently arrive with an older frame stamp.
  // Keep the canonical door clock monotonic across those two schedulers.
  const sampleTimeMs = Math.max(nowHostTimeMs, prior.updatedAtMs);
  const observerPositions = admittedGunRangeClockParticipants()
    .filter((participant) => participant.admitted && participant.connected && participant.alive)
    .map((participant) => participant.position);
  gunRangeTestBayDoorState = advanceGunRangeTestBayDoorForObservers(
    prior,
    sampleTimeMs,
    observerPositions,
  ).state;
  return gunRangeTestBayDoorState;
}

function projectActiveGunRangeTestBayDoor(nowLocalMonoMs: number): GunRangeTestBayDoorState | null {
  if (selectedArena.id !== 'gun-range' || matchState.phase !== 'active' || !gunRangeTestBayDoorState) return null;
  if (network.role !== 'client') return gunRangeTestBayDoorState;
  const sampleAtLocalMonoMs = hostTimeToGuestMono(
    hostTimeMapping,
    gunRangeTestBayDoorState.updatedAtMs,
    nowLocalMonoMs,
    privateLobbySnapshot?.snapshotHostTimeMs ?? gunRangeTestBayDoorState.updatedAtMs,
  );
  // A replacement document can have a younger performance time origin than
  // the host sample it is projecting. Preserve monotonic age while bounding
  // the replica timestamp to the non-negative local clock domain accepted by
  // the strict door-state contract.
  const projectedUpdatedAtMs = Math.max(0, Math.min(nowLocalMonoMs, sampleAtLocalMonoMs));
  return projectGunRangeTestBayDoorState(
    { ...gunRangeTestBayDoorState, updatedAtMs: projectedUpdatedAtMs },
    nowLocalMonoMs,
  );
}

function initializeGunRangeTestBayDoor(mode: 'solo' | 'host' | 'client'): void {
  gunRangeTestBayDoorBroadcastPending = false;
  if (selectedArena.id !== 'gun-range') {
    gunRangeTestBayDoorState = null;
    gunRangeTestBayDoorColliders = Object.freeze([]);
    gunRangeTestBayDoorBallisticSurfaces = Object.freeze([]);
    gunRangeTestBayDoorColliderArena = null;
    presentedGunRangeTestBayDoorThumpSequence = 0;
    return;
  }
  if (mode === 'client') gunRangeTestBayDoorState = privateLobbySnapshot?.testBayDoor ?? null;
  if (!gunRangeTestBayDoorState) gunRangeTestBayDoorState = createGunRangeTestBayDoorState(performance.now());
  const state = projectActiveGunRangeTestBayDoor(performance.now()) ?? gunRangeTestBayDoorState;
  const frame = applyGunRangeTestBayDoorState(arena.root, state);
  gunRangeTestBayDoorColliderArena = arena.root;
  gunRangeTestBayDoorColliders = frame.dynamicColliders;
  gunRangeTestBayDoorBallisticSurfaces = frame.dynamicBallisticSurfaces;
  presentedGunRangeTestBayDoorThumpSequence = state.thumpSequence;
  syncInteractiveWorldPhysics();
}

function updateGunRangeTestBayDoorAuthority(nowLocalMonoMs: number): GunRangeTestBayDoorState | null {
  if (!gameStarted || selectedArena.id !== 'gun-range' || matchState.phase !== 'active') return null;
  if (network.role === 'client') return projectActiveGunRangeTestBayDoor(nowLocalMonoMs);
  const priorPhase = gunRangeTestBayDoorState?.phase ?? 'closed';
  const priorThump = gunRangeTestBayDoorState?.thumpSequence ?? 0;
  const state = sampleAuthoritativeGunRangeTestBayDoor(nowLocalMonoMs);
  if (state && network.role === 'host'
    && (state.phase !== priorPhase || state.thumpSequence !== priorThump)) {
    gunRangeTestBayDoorBroadcastPending = true;
  }
  return state;
}

function synchronizeGunRangeTestBayDoorWorld(
  doorState: GunRangeTestBayDoorState,
  presentThump: boolean,
): void {
  if (selectedArena.id !== 'gun-range') return;
  const doorFrame = applyGunRangeTestBayDoorState(arena.root, doorState);
  const doorArenaChanged = gunRangeTestBayDoorColliderArena !== arena.root;
  gunRangeTestBayDoorColliderArena = arena.root;
  gunRangeTestBayDoorColliders = doorFrame.dynamicColliders;
  gunRangeTestBayDoorBallisticSurfaces = doorFrame.dynamicBallisticSurfaces;
  if (doorState.thumpSequence > presentedGunRangeTestBayDoorThumpSequence) {
    presentedGunRangeTestBayDoorThumpSequence = doorState.thumpSequence;
    if (presentThump) {
      const trigger = GUN_RANGE_TEST_BAY_CONTRACT.door.trigger;
      audio.testBayDoorThump(player.position.distanceTo(new THREE.Vector3(trigger.x, trigger.y, trigger.z)));
    }
  }
  if (doorArenaChanged || doorFrame.collisionChanged) syncInteractiveWorldPhysics();
}

function flushGunRangeTestBayDoorBroadcast(): void {
  if (!gunRangeTestBayDoorBroadcastPending || network.role !== 'host') return;
  gunRangeTestBayDoorBroadcastPending = false;
  broadcastHostLobby('active');
}

function sampleAuthoritativeGunRangeMatchClock(nowHostTimeMs: number): GunRangeMatchClockSnapshot | null {
  const durationMs = gunRangeMatchClockDurationMs();
  if (durationMs === null || network.role === 'client') return null;
  if (!gunRangeMatchClockState) {
    if (matchState.phase !== 'active') return null;
    gunRangeMatchClockState = createGunRangeMatchClockSnapshot(durationMs, nowHostTimeMs);
  }
  const sampleTimeMs = Math.max(nowHostTimeMs, gunRangeMatchClockState.sampledAtHostTimeMs);
  gunRangeMatchClockState = advanceGunRangeMatchClock(
    gunRangeMatchClockState,
    sampleTimeMs,
    gunRangeMatchClockState.paused,
    durationMs,
  ).state;
  return gunRangeMatchClockState;
}

function projectActiveGunRangeMatchClock(nowLocalMonoMs: number): void {
  const durationMs = gunRangeMatchClockDurationMs();
  if (durationMs === null || !gunRangeMatchClockState || matchState.phase !== 'active') return;
  const sampleAtLocalMonoMs = network.role === 'client'
    ? hostTimeToGuestMono(
        hostTimeMapping,
        gunRangeMatchClockState.sampledAtHostTimeMs,
        nowLocalMonoMs,
        privateLobbySnapshot?.snapshotHostTimeMs ?? gunRangeMatchClockState.sampledAtHostTimeMs,
      )
    : gunRangeMatchClockState.sampledAtHostTimeMs;
  matchState = {
    ...matchState,
    ...projectGunRangeMatchClock(
      gunRangeMatchClockState,
      sampleAtLocalMonoMs,
      nowLocalMonoMs,
      durationMs,
    ),
  };
}

function initializeGunRangeMatchClock(mode: 'solo' | 'host' | 'client'): void {
  gunRangeMatchClockOccupantIds = Object.freeze([]);
  const durationMs = gunRangeMatchClockDurationMs();
  if (durationMs === null) {
    gunRangeMatchClockState = null;
    return;
  }
  if (mode === 'client') {
    gunRangeMatchClockState = privateLobbySnapshot?.matchClock ?? null;
    projectActiveGunRangeMatchClock(performance.now());
    return;
  }
  if (!gunRangeMatchClockState) {
    // Admission/prewarm can finish after the scheduled lobby boundary. A new
    // Gun Range round nevertheless begins with the full exact two minutes;
    // only the host-authored post-admission clock may consume that budget.
    const activeAt = matchState.phase === 'active' ? performance.now() : matchState.endsAt;
    gunRangeMatchClockState = createGunRangeMatchClockSnapshot(durationMs, activeAt);
  }
  projectActiveGunRangeMatchClock(performance.now());
}

function updateGunRangeMatchClockAuthority(nowLocalMonoMs: number): void {
  const durationMs = gunRangeMatchClockDurationMs();
  if (!gameStarted || durationMs === null || matchState.phase !== 'active') return;
  if (network.role === 'client') {
    projectActiveGunRangeMatchClock(nowLocalMonoMs);
    return;
  }
  if (!gunRangeMatchClockState) {
    gunRangeMatchClockState = createGunRangeMatchClockSnapshot(durationMs, nowLocalMonoMs);
  }
  const previousOccupantIds = gunRangeMatchClockOccupantIds;
  const nextOccupantIds = gunRangeTestBayOccupants(
    admittedGunRangeClockParticipants(),
    GUN_RANGE_TEST_BAY_CONTRACT.bay.bounds,
  );
  const boundaryEdgeCount = gunRangeTestBayOccupancyBoundaryCount(previousOccupantIds, nextOccupantIds);
  gunRangeMatchClockOccupantIds = nextOccupantIds;
  const sampleTimeMs = Math.max(nowLocalMonoMs, gunRangeMatchClockState.sampledAtHostTimeMs);
  const step = advanceGunRangeMatchClock(
    gunRangeMatchClockState,
    sampleTimeMs,
    gunRangeMatchClockOccupantIds.length > 0,
    durationMs,
    boundaryEdgeCount,
  );
  gunRangeMatchClockState = step.state;
  projectActiveGunRangeMatchClock(nowLocalMonoMs);
  if (step.boundaryEdgeCount > 0 && network.role === 'host') {
    // Participant boundary edges are infrequent but release-critical. Make them crash-durable
    // before publishing the newer reliable lobby revision to connected peers.
    persistActiveHostMatchCheckpoint(true);
    broadcastHostLobby('active');
  }
}

function hostSnapshot(phase: LobbySnapshot['phase'] = privateLobbySnapshot?.phase ?? 'waiting'): LobbySnapshot {
  const members = [...hostLobbyMembers.values()].sort((a, b) => Number(b.id === player.id) - Number(a.id === player.id) || a.id.localeCompare(b.id));
  const scoreIds = [
    ...members.map((member) => member.id),
    ...hostedBotIds(privateMatchConfig.hostedBotCount),
  ];
  // Active lobby heartbeats are also score-repair snapshots. Keep host-owned
  // bot rows in the canonical envelope so a guest cannot receive a complete
  // match-score commit and then regress to a human-only scoreboard on the next
  // clock-ping lobby broadcast. Before deployment, absent bot rows stay absent.
  const scores = scoreIds
    .map((id) => authoritativeScores.get(id) ?? (hostLobbyMembers.has(id) ? emptyPlayerScore(id) : undefined))
    .filter((score): score is PlayerScore => score !== undefined);
  // The reliable envelope must never predate either canonical subsystem. A
  // queued rAF timestamp may be marginally ahead of performance.now(), and a
  // replica correctly rejects any child sample that appears to come from the
  // future of its enclosing host snapshot.
  const snapshotHostTimeMs = Math.max(
    performance.now(),
    gunRangeMatchClockState?.sampledAtHostTimeMs ?? 0,
    gunRangeTestBayDoorState?.updatedAtMs ?? 0,
  );
  const matchClock = phase === 'active'
    ? sampleAuthoritativeGunRangeMatchClock(snapshotHostTimeMs)
    : null;
  const testBayDoor = phase === 'active'
    ? sampleAuthoritativeGunRangeTestBayDoor(snapshotHostTimeMs)
    : null;
  // HF-347: every lobby heartbeat repairs guest training-dummy lifecycle
  // state, so peers who never saw a shot result (observers, rejoiners) still
  // converge on the host's active/health/respawn truth within one heartbeat.
  const testDummies = phase === 'active' && privateMatchConfig.arenaId === 'gun-range'
    ? arena.targets
      .filter((target) => target.kind === 'training-dummy')
      .map((target) => Object.freeze({
        id: target.id,
        active: target.active,
        health: Math.max(0, target.health),
        respawnAtHostTimeMs: Math.max(0, target.respawnAt),
      }))
    : null;
  const domination = phase === 'active' && privateMatchConfig.mode === 'domination' && dominationState
    ? Object.freeze({
      zones: dominationState.zones.map((zone) => Object.freeze({
        id: zone.id, owner: zone.owner, capturingTeam: zone.capturingTeam,
        progress: Math.max(0, Math.min(1, zone.progress)), contested: zone.contested,
      })),
      scores: [dominationState.scores[0], dominationState.scores[1]] as const,
    })
    : null;
  return {
    revision: privateLobbyRevision,
    hostId: player.id,
    phase,
    config: privateMatchConfig,
    members,
    scores,
    snapshotHostTimeMs,
    activeAtHostTimeMs: privateMatchActiveAtHostTimeMs,
    activeAtEpochMs: privateMatchActiveAtEpochMs,
    matchClock,
    testBayDoor,
    testDummies,
    domination,
  };
}

function broadcastHostLobby(phase: LobbySnapshot['phase'] = privateLobbySnapshot?.phase ?? 'waiting'): void {
  if (network.role !== 'host') return;
  const localMember = hostLobbyMembers.get(player.id);
  if (localMember) {
    player.team = localMember.team;
    element<HTMLSelectElement>('#team').value = String(localMember.team);
  }
  privateLobbyRevision += 1;
  privateLobbySnapshot = hostSnapshot(phase);
  if (privateLobbySnapshot.testBayDoor && selectedArena.id === 'gun-range' && matchState.phase === 'active') {
    // hostSnapshot advances the canonical door to the reliable envelope's
    // exact host timestamp. Apply that exact state to the leaf, movement,
    // ballistics and Rapier before any peer can observe the newer snapshot.
    synchronizeGunRangeTestBayDoorWorld(
      privateLobbySnapshot.testBayDoor,
      document.visibilityState === 'visible' && document.hasFocus(),
    );
  }
  network.setCapacity(privateLobbySnapshot.config.capacity);
  for (const member of privateLobbySnapshot.members) network.setPlayerTeam(member.id, member.team);
  const message: LobbyStateMessage = { type: 'lobby-state', by: player.id, snapshot: privateLobbySnapshot, nonce: randomNonce() };
  network.send(message);
  // HF-325: the mandate is elected from the roster revision that just shipped,
  // so it must go out AFTER the lobby-state that guests will recompute from.
  publishHostSuccessionMandate();
  renderPrivateLobby();
  renderTextChat();
}

/** HF-325: re-mint and rebroadcast the mandate whenever the roster moves. */
function publishHostSuccessionMandate(): void {
  if (network.role !== 'host' || !network.roomCode) return;
  const roster = successionRoster();
  if (!roster) return;
  const result = publishSuccessionMandate(hostSuccessionPublisher, {
    roster,
    roomCode: network.roomCode,
    nowEpochMs: Date.now(),
    nonce: randomNonce(),
  });
  hostSuccessionPublisher = result.publisher;
  lastSuccessionPublish = {
    reason: result.reason,
    sent: result.broadcast !== null,
    rosterRevision: roster.revision,
  };
  if (result.broadcast) network.send(result.broadcast);
}

/**
 * HF-325: ship the adoptable mirror to the current mandate holder, from the
 * SAME checkpoint object that gets persisted, so what the successor holds is
 * exactly what the host would itself have recovered from. Unicast, never
 * broadcast: it carries every guest's resume-token digest.
 */
function shipAuthorityMirror(checkpoint: HostMatchCheckpoint): void {
  if (network.role !== 'host') return;
  const plan = planAuthorityMirrorSend(hostSuccessionPublisher, {
    checkpoint,
    nowMonoMs: performance.now(),
    nowEpochMs: Date.now(),
    nonce: randomNonce(),
    // null is fine — the mirror stamps UNCLAIMABLE_RESUME_TOKEN_DIGEST and the
    // demoted host re-joins through normal admission. Fail-closed.
    outgoingHostResumeTokenSha256: null,
  });
  hostSuccessionPublisher = plan.publisher;
  lastMirrorShip = { reason: plan.reason };
  // A missing mirror costs a dead room; a wrong one costs a split brain.
  if (plan.send) network.sendToPlayer(plan.send.forPlayerId, plan.send);
}


// HF-323: hold the start while any guest admission is in-flight or transport connection is pending
function hostHasPendingGuestConnection(): boolean {
  if (network.role !== 'host') return false;
  if (hostLobbyAdmissionInFlight.size > 0 || pendingHostRecoveryJoins.size > 0) return true;
  try {
    const diag = network.diagnostics();
    if (Number(diag.guestConnections) > network.connectedPlayerIds().length) return true;
    if (Number(diag.pendingStateChannels) > 0) return true;
  } catch {
    // network diagnostics unavailable or offline
  }
  return false;
}

function hostLobbyAdmissionAttemptCurrent(attempt: HostLobbyAdmissionAttempt): boolean {
  const queuedReplacement = pendingHostRecoveryJoins.get(attempt.playerId);
  return hostLobbyAdmissionAttemptIsCurrent(attempt, {
    role: network.role,
    generation: hostLobbySessionGeneration,
    currentAttempt: hostLobbyAdmissionInFlight.get(attempt.playerId),
    queuedConnectionEpoch: queuedReplacement?.connectionEpoch,
  });
}

async function rememberHostLobbyResumeTokenDigest(
  playerId: string,
  token: string,
  attempt: HostLobbyAdmissionAttempt,
): Promise<boolean> {
  try {
    const sha256 = await sha256ResumeToken(token);
    if (!hostLobbyAdmissionAttemptCurrent(attempt)) return false;
    hostLobbyTokenDigests.set(playerId, {
      playerId,
      sha256,
      expiresAtEpochMs: Date.now() + HOST_MATCH_CHECKPOINT_TTL_MS,
    });
    return true;
  } catch {
    if (!hostLobbyAdmissionAttemptCurrent(attempt)) return false;
    // Multiplayer remains available when Web Crypto is blocked, but an active
    // match cannot be crash-restored without a non-reversible guest credential.
    hostLobbyTokenDigests.delete(playerId);
    return false;
  }
}

function checkpointFlareShooterFeedback(
  authority: FlareAuthorityContinuationCheckpoint,
  nowMonoMs: number,
): readonly FlareShooterFeedbackCheckpoint[] | null {
  if (!Number.isFinite(nowMonoMs)) return null;
  const activeEffects = new Map(authority.effects.map((effect) => [
    `${effect.ownerId}:${effect.actionNonce}`,
    effect,
  ]));
  const feedback = new Map<string, FlareShooterFeedbackCheckpoint>();
  const capture = (
    context: PendingFlareShotRequest,
    remainingMs: number,
  ): void => {
    const request = context.request;
    const key = `${request.by}:${request.nonce}`;
    const effect = activeEffects.get(key);
    const pellet = request.pelletDirections.length === 1 ? request.pelletDirections[0] : undefined;
    if (!effect || !pellet || remainingMs <= 0) return;
    feedback.set(key, Object.freeze({
      ownerId: request.by,
      actionNonce: request.nonce,
      shotId: request.shotId,
      connectionEpoch: request.connectionEpoch,
      lifeId: request.lifeId,
      shotSeq: request.shotSeq,
      weaponSequence: request.weaponSequence,
      fireTimeMs: request.fireTimeMs,
      triggerStartedAtMs: request.triggerStartedAtMs,
      targetViewTimeMs: request.targetViewTimeMs,
      origin: Object.freeze([...request.origin] as [number, number, number]),
      // Persist the host-admitted projectile ray, not a separately claimed
      // generic direction that a crafted request could make disagree.
      direction: Object.freeze([...pellet] as [number, number, number]),
      pelletDirections: Object.freeze([
        Object.freeze([...pellet] as [number, number, number]),
      ]) as readonly [readonly [number, number, number]],
      receivedAtHostTimeMs: context.receivedAtHostTimeMs,
      appliedRewindMs: context.appliedRewindMs,
      remainingMs,
    }));
  };
  for (const pending of pendingFlareShotRequests.values()) {
    const effect = activeEffects.get(`${pending.request.by}:${pending.request.nonce}`);
    if (!effect) continue;
    capture(
      pending,
      effect.remainingMs + (effect.phase === 'flight' ? FLARE_PROJECTILE_EFFECT.burnDurationMs + 1_000 : 1_000),
    );
  }
  for (const context of flareShotResultContexts.values()) {
    capture(context, context.expiresAt - nowMonoMs);
  }
  const entries = Object.freeze([...feedback.values()].sort((left, right) => {
    if (left.ownerId < right.ownerId) return -1;
    if (left.ownerId > right.ownerId) return 1;
    return left.actionNonce - right.actionNonce;
  }));
  return isFlareShooterFeedbackCheckpoints(entries, authority) ? entries : null;
}

function canonicalRetainedGuestSnapshot(
  source: PlayerSnapshot,
  member: LobbyMember,
  score: PlayerScore,
  health: RemoteHealthAuthorityState,
): PlayerSnapshot {
  let weapon = source.weapon;
  if (weapon === 'railgun' && railgunState.holderId !== source.id) weapon = source.primary;
  if (isTimedMapWeaponId(weapon) && timedMapWeaponStates[weapon].holderId !== source.id) weapon = source.primary;
  // Project EXACTLY the bounded checkpoint field set. A blind spread carried
  // HF-358's optional `swimming` flag into the document, and the checkpoint
  // validator's exact-key contract refused EVERY guest entry — no checkpoint
  // was ever persisted, so the authority mirror never shipped and host
  // succession could not fire in a real match. New PlayerSnapshot fields must
  // be added HERE deliberately, together with the wire validator, never by
  // riding a spread.
  return {
    id: source.id,
    name: member.name,
    team: member.team,
    x: source.x,
    y: source.y,
    z: source.z,
    yaw: source.yaw,
    pitch: source.pitch,
    hp: health.hp,
    kills: score.kills,
    deaths: score.deaths,
    primary: source.primary,
    secondary: source.secondary,
    grenade: source.grenade,
    weapon,
    stance: source.stance ?? 'stand',
    seq: source.seq,
  };
}

function createHostMatchCheckpoint(
  nowEpochMs = Date.now(),
  nowMonoMs = performance.now(),
): HostMatchCheckpoint | null {
  // QA diagnostics: a silent null here starves the authority mirror with no
  // observable difference from "not wired". Name the first failing guard.
  const refuse = (reason: string): null => {
    lastCheckpointRefusal = reason;
    return null;
  };
  if (network.role !== 'host' || !gameStarted || matchFinished) return refuse('not-live-host');
  if (matchState.phase !== 'warmup' && matchState.phase !== 'active') return refuse('phase-not-live');
  if (!network.roomCode || privateMatchActiveAtHostTimeMs === null || privateMatchActiveAtEpochMs === null) return refuse('no-active-clock');
  // Project the exact 7-key member shape the checkpoint validator demands.
  // HF-328/HF-360 added squadName/squadColor/skinId to LobbyMember; a blind
  // spread carried them into the document and isExactLobbyMember refused the
  // whole checkpoint — the same silent-starvation class as the guest
  // snapshot's `swimming` drift. New LobbyMember fields must be added HERE
  // deliberately, together with the wire validator, never by riding a spread.
  const members = [...hostLobbyMembers.values()]
    .map((member) => ({
      id: member.id,
      name: member.name,
      team: member.team,
      ready: member.ready,
      connected: member.connected,
      pingMs: member.pingMs,
      dhv: member.dhv,
    }))
    .sort((a, b) => Number(b.id === player.id) - Number(a.id === player.id) || a.id.localeCompare(b.id));
  const hostedBots = [...bots.values()]
    .filter((bot) => bot.id.startsWith('host-bot-'))
    .sort((a, b) => a.id.localeCompare(b.id));
  if (hostedBots.length !== privateMatchConfig.hostedBotCount) return refuse('bot-count-mismatch');
  const scores = [...authoritativeScores.values()]
    .filter((score) => members.some((member) => member.id === score.id) || hostedBots.some((bot) => bot.id === score.id))
    .sort((a, b) => a.id.localeCompare(b.id));
  const hostScore = scores.find((score) => score.id === player.id);
  const hostMember = members.find((member) => member.id === player.id);
  if (!hostScore || !hostMember || hostedBots.some((bot) => {
    const score = scores.find((candidate) => candidate.id === bot.id);
    return score?.kills !== bot.kills || score.deaths !== bot.deaths;
  })) return refuse('score-or-member-mismatch');
  const expiresAtEpochMs = nowEpochMs + HOST_MATCH_CHECKPOINT_TTL_MS;
  const resumeTokenDigests: ResumeTokenDigestCheckpoint[] = [];
  for (const member of members) {
    if (member.id === player.id) continue;
    const digest = hostLobbyTokenDigests.get(member.id);
    if (!digest) return refuse(`missing-resume-digest:${member.id}`);
    resumeTokenDigests.push({ ...digest, expiresAtEpochMs });
  }
  const timedMapWeapons = checkpointTimedMapWeaponAuthorities(timedMapWeaponStates, nowMonoMs);
  if (!timedMapWeapons) return refuse('timed-map-weapons');
  const flareProjectiles = flareProjectileSystem.checkpointAuthority(nowMonoMs);
  if (!flareProjectiles) return refuse('flare-projectiles');
  const flareShotFeedback = checkpointFlareShooterFeedback(flareProjectiles, nowMonoMs);
  if (!flareShotFeedback) return refuse('flare-feedback');
  const killstreak = killstreakRuntime.checkpoint(nowMonoMs);
  if (!killstreak) return refuse('killstreak');
  const guests: GuestAuthorityCheckpoint[] = [];
  for (const member of members) {
    if (member.id === player.id) continue;
    const remote = remotes.get(member.id);
    const retained = retainedRemoteAuthorities.get(member.id);
    const source = remote
      ? { snapshot: remote.snapshot, continuity: remote.continuity }
      : retained;
    const score = scores.find((candidate) => candidate.id === member.id);
    const priorHealth = remoteHealthAuthorities.get(member.id);
    if (!source || !score || !priorHealth) return refuse(`guest-authority-missing:${member.id}`);
    const health = advanceRemoteHealthAuthority(priorHealth, nowMonoMs);
    remoteHealthAuthorities.set(member.id, health);
    const snapshot = canonicalRetainedGuestSnapshot(source.snapshot, member, score, health);
    if (remote) remote.snapshot = snapshot;
    const continuity = killstreakRuntime.actorLifeId(member.id) ?? source.continuity;
    retainedRemoteAuthorities.set(member.id, Object.freeze({ snapshot: Object.freeze({ ...snapshot }), continuity }));
    const combatInventory = remoteCombatInventories.get(member.id);
    if (!combatInventory) return refuse(`combat-inventory-missing:${member.id}`);
    const guest = checkpointGuestAuthority(snapshot, continuity, health, combatInventory, nowMonoMs);
    if (!guest) {
      // host-match-checkpoint.ts owns the real predicate; this replica names
      const expectedKeys = ['id', 'name', 'team', 'x', 'y', 'z', 'yaw', 'pitch', 'hp', 'kills', 'deaths', 'primary', 'secondary', 'grenade', 'weapon', 'stance', 'seq'];
      const extraKeys = Object.keys(snapshot).filter((key) => !expectedKeys.includes(key));
      const missingKeys = expectedKeys.filter((key) => !(key in snapshot));
      const stanceOk = snapshot.stance === 'stand' || snapshot.stance === 'crouch' || snapshot.stance === 'prone';
      const why = missingKeys.length ? `snapshot-missing:${missingKeys.join(',')}`
        : extraKeys.length ? `snapshot-extra:${extraKeys.join(',')}`
        : !stanceOk ? `stance:${String(snapshot.stance)}`
        : !Number.isInteger(snapshot.kills) || snapshot.kills < 0 || snapshot.kills > 500 ? `kills:${snapshot.kills}`
        : !Number.isInteger(snapshot.deaths) || snapshot.deaths < 0 || snapshot.deaths > 500 ? `deaths:${snapshot.deaths}`
        : !Number.isFinite(health.hp) || health.hp < 0 || health.hp > 100 ? `hp:${health.hp}`
        : health.alive !== (health.hp > 0) ? `alive:${String(health.alive)}-hp:${health.hp}`
        : snapshot.hp !== health.hp ? `snapshot-hp:${snapshot.hp}-health-hp:${health.hp}`
        : !isGuestCombatInventory(combatInventory) ? 'inventory-shape'
        : !guestCombatInventoryWithinWeaponCaps(combatInventory) ? 'inventory-caps'
        : !Number.isSafeInteger(continuity) || continuity < 1 || continuity > 1_000_000_000 ? `continuity:${continuity}`
        : 'checkpoint-schema';
      return refuse(`guest-checkpoint-invalid:${member.id}:${why}`);
    }
    guests.push(guest);
  }
  const railgun = checkpointRailgunAuthority(railgunState, nowMonoMs);
  if (!railgun) return refuse('railgun');
  const matchClock = privateMatchConfig.arenaId === 'gun-range' && matchState.phase === 'active'
    ? sampleAuthoritativeGunRangeMatchClock(nowMonoMs)
    : null;
  if (privateMatchConfig.arenaId === 'gun-range' && matchState.phase === 'active' && !matchClock) return refuse('gun-range-clock');
  const elapsedSinceActiveMs = matchClock
    ? privateMatchConfig.durationMs - matchClock.remainingMs
    : nowMonoMs - privateMatchActiveAtHostTimeMs;
  const checkpoint: HostMatchCheckpoint = {
    schemaVersion: HOST_MATCH_CHECKPOINT_SCHEMA_VERSION,
    protocolVersion: MULTIPLAYER_PROTOCOL_VERSION,
    savedAtEpochMs: nowEpochMs,
    expiresAtEpochMs,
    roomCode: network.roomCode,
    activeAtEpochMs: privateMatchActiveAtEpochMs,
    matchEpoch: killstreakMatchEpoch,
    phase: matchState.phase,
    elapsedSinceActiveMs,
    lobbyRevision: privateLobbyRevision,
    config: privateMatchConfig,
    members,
    scores,
    hostPlayer: {
      id: player.id,
      name: hostMember.name,
      team: hostMember.team,
      x: player.position.x,
      y: player.position.y,
      z: player.position.z,
      vx: player.velocity.x,
      vy: player.velocity.y,
      vz: player.velocity.z,
      yaw: player.yaw,
      pitch: player.pitch,
      hp: player.hp,
      alive: player.alive,
      kills: hostScore.kills,
      deaths: hostScore.deaths,
      primary: player.primaryWeapon,
      secondary: player.secondaryWeapon,
      grenade: player.selectedGrenade,
      weapon: player.weapon,
      stance: player.stance,
      grenades: player.grenades,
      ammo: { ...player.ammo },
      reserve: { ...player.reserve },
      continuity: localContinuity,
      seq: player.seq,
      respawnRemainingMs: player.alive ? 0 : Math.max(1, respawnEndsAt - nowMonoMs),
      invulnerabilityRemainingMs: Math.max(0, player.invulnerableUntil - nowMonoMs),
    },
    guests,
    bots: hostedBots.map((bot) => ({
      snapshot: hostedBotSnapshot(bot, Math.max(hostedBotStateSeq, Number(bot.root.userData.networkSeq ?? 0))),
      grenade: bot.grenade,
      continuity: bot.continuity,
      vx: bot.velocity.x,
      vy: bot.velocity.y,
      vz: bot.velocity.z,
      waypoint: bot.waypoint,
      strafeSign: bot.strafeSign,
      respawnRemainingMs: bot.alive ? 0 : Math.max(1, bot.respawnAt - nowMonoMs),
      invulnerabilityRemainingMs: Math.max(0, bot.invulnerableUntil - nowMonoMs),
      nextGrenadeRemainingMs: Math.max(0, bot.nextGrenadeAt - nowMonoMs),
    })),
    resumeTokenDigests,
    railgun,
    killstreak,
    timedMapWeapons,
    ...(matchClock ? { matchClock } : {}),
    flareProjectiles,
    flareShotFeedback,
  };
  return checkpoint;
}

let lastHostCheckpointPersistAtEpochMs = 0;
let lastCheckpointAttempt: { atEpochMs: number; hadCheckpoint: boolean; rejectReason: string | null } | null = null;
let lastCheckpointRefusal: string | null = null;
let hostCheckpointPersistScheduled = false;
let hostCheckpointRejectedPoseWrites = 0;
let lastHostCheckpointRejectedPoseReason: string | null = null;
let lastHostCheckpointRejectedPoseAtEpochMs: number | null = null;
const HOST_CHECKPOINT_PERSIST_INTERVAL_MS = 2_000;
const HOST_CHECKPOINT_IDLE_TIMEOUT_MS = 250;

function hostRecoveryPoseAudit(checkpoint: HostMatchCheckpoint): HostRecoveryPoseAudit {
  return auditHostRecoveryPoses(checkpoint, selectedArena.id, arena.bounds, activeWorldColliders());
}

function createRecoverySafeHostMatchCheckpoint(): HostMatchCheckpoint | null {
  const checkpoint = createHostMatchCheckpoint();
  if (!checkpoint) return null;
  const audit = hostRecoveryPoseAudit(checkpoint);
  if (audit.accepted) return checkpoint;
  hostCheckpointRejectedPoseWrites += 1;
  lastHostCheckpointRejectedPoseReason = audit.reason;
  lastHostCheckpointRejectedPoseAtEpochMs = Date.now();
  // Deliberately retain the prior known-safe localStorage receipt. A transient
  // collider-invalid pose must not replace the only checkpoint that can be
  // admitted after a renderer crash.
  return null;
}
/**
 * Persist the bounded host checkpoint. Serializing the entire match state
 * (bots, inventories, flare projectiles) and writing localStorage on the shot
 * frame caused the reported flare-gun freeze. Writes are throttled to the
 * documented two-second cadence and deferred to the idle lane; the most recent
 * state is always what gets written.
 */
function persistActiveHostMatchCheckpoint(force = false): boolean {
  const storage = clientPersistentStorage();
  if (!storage) return false;
  if (force) {
    lastHostCheckpointPersistAtEpochMs = Date.now();
    const checkpoint = createRecoverySafeHostMatchCheckpoint();
    if (checkpoint) shipAuthorityMirror(checkpoint); // HF-325
    return checkpoint ? saveHostMatchCheckpoint(storage, checkpoint) : false;
  }
  if (hostCheckpointPersistScheduled) return true;
  hostCheckpointPersistScheduled = true;
  scheduleBrowserPreparationIdleTask(() => {
    hostCheckpointPersistScheduled = false;
    const deferredStorage = clientPersistentStorage();
    if (!deferredStorage) return;
    const nowEpochMs = Date.now();
    const remainingThrottleMs = HOST_CHECKPOINT_PERSIST_INTERVAL_MS
      - (nowEpochMs - lastHostCheckpointPersistAtEpochMs);
    if (remainingThrottleMs > 0) {
      // Keep one coalesced dirty write alive. Dropping it here made a mutation
      // just after the prior checkpoint wait for a second interval tick.
      hostCheckpointPersistScheduled = true;
      window.setTimeout(() => {
        hostCheckpointPersistScheduled = false;
        persistActiveHostMatchCheckpoint();
      }, remainingThrottleMs);
      return;
    }
    lastHostCheckpointPersistAtEpochMs = nowEpochMs;
    const checkpoint = createRecoverySafeHostMatchCheckpoint();
    lastCheckpointAttempt = {
      atEpochMs: nowEpochMs,
      hadCheckpoint: checkpoint !== null,
      rejectReason: checkpoint === null
        ? (lastHostCheckpointRejectedPoseReason ?? lastCheckpointRefusal)
        : null,
    };
    if (checkpoint) {
      saveHostMatchCheckpoint(deferredStorage, checkpoint);
      shipAuthorityMirror(checkpoint); // HF-325
    }
  }, HOST_CHECKPOINT_IDLE_TIMEOUT_MS);
  return true;
}

function clearStoredHostMatchCheckpoint(): void {
  const storage = clientPersistentStorage();
  if (storage) clearHostMatchCheckpoint(storage);
  pendingHostMatchRecovery = null;
}

function refreshHostMatchRecoveryAffordance(): HostMatchCheckpoint | null {
  const roomCode = loadLastHostedRoomCode(clientPersistentStorage()) ?? '';
  const storage = clientPersistentStorage();
  pendingHostMatchRecovery = roomCode && storage
    ? loadHostMatchCheckpoint(storage, MULTIPLAYER_PROTOCOL_VERSION, roomCode)
    : null;
  const hostButton = element<HTMLButtonElement>('#host');
  hostButton.dataset.recoveryAvailable = pendingHostMatchRecovery ? 'true' : 'false';
  hostButton.textContent = pendingHostMatchRecovery ? 'RESUME HOSTED MATCH' : 'HOST LOBBY';
  hostButton.title = pendingHostMatchRecovery
    ? 'Reclaim the same room and continue the bounded active-match checkpoint.'
    : 'Open a new private lobby.';
  return pendingHostMatchRecovery;
}

function refreshGuestMatchRecoveryAffordance(): void {
  const roomInput = element<HTMLInputElement>('#room-input');
  const joinButton = element<HTMLButtonElement>('#join');
  const affordance = guestRejoinAffordance(roomInput.value, loadLastRoomCode(localStorage));
  joinButton.dataset.rejoinAvailable = String(affordance.available);
  joinButton.textContent = affordance.label;
  joinButton.title = affordance.title;
}


function restoreRecoveredHostRuntime(checkpoint: HostMatchCheckpoint, nowMonoMs = performance.now()): number {
  const poseAudit = hostRecoveryPoseAudit(checkpoint);
  if (!poseAudit.accepted) throw new Error(`Stored host recovery positions are unsafe: ${poseAudit.reason}`);
  const hostState = checkpoint.hostPlayer;
  const hostScore = checkpoint.scores.find((score) => score.id === hostState.id);
  if (!hostScore || player.id !== hostState.id) throw new Error('Stored host recovery identity is inconsistent');
  authoritativeScores.clear();
  for (const score of checkpoint.scores) authoritativeScores.set(score.id, score);
  player.name = hostState.name;
  player.team = hostState.team;
  player.position.set(hostState.x, hostState.y, hostState.z);
  player.velocity.set(hostState.vx, hostState.vy, hostState.vz);
  player.yaw = hostState.yaw;
  player.pitch = hostState.pitch;
  player.hp = hostState.hp;
  player.alive = hostState.alive;
  player.kills = hostScore.kills;
  player.deaths = hostScore.deaths;
  player.primaryWeapon = hostState.primary;
  player.secondaryWeapon = hostState.secondary;
  player.selectedGrenade = hostState.grenade;
  player.weapon = hostState.weapon;
  player.stance = hostState.stance;
  // HF-412: an authority restore is a teleport, not a player-initiated stance
  // change. Drop any drop-shot transition still in flight so the rendered eye
  // does not keep an offset from a pose this player no longer has.
  stanceTransition = null;
  stanceTransitionSample = restingStanceTransitionSample(player.stance);
  player.grenades = hostState.grenades;
  player.ammo = { ...hostState.ammo };
  player.reserve = { ...hostState.reserve };
  player.reloadState = null;
  player.switchingUntil = 0;
  player.seq = hostState.seq;
  localContinuity = hostState.continuity;
  roundDamageDealt = hostScore.damageDealt;
  roundDamageTaken = hostScore.damageTaken;
  player.invulnerableUntil = nowMonoMs + recoveryRemainingMs(hostState.invulnerabilityRemainingMs, checkpoint);
  if (characterPhysics && !characterPhysics.setStance(hostState.stance)) {
    throw new Error('Stored host stance does not fit authoritative collision');
  }
  characterPhysics?.teleportEye(player.position);
  camera.position.copy(player.position);
  camera.rotation.set(player.pitch, player.yaw, 0, 'YXZ');
  camera.updateMatrixWorld(true);
  weaponView.setWeapon(player.weapon, true);
  weaponView.setPresentationVisible(player.alive);
  localPositionHistory.length = 0;
  localPositionHistory.push({
    at: currentHostTimeMs(), x: player.position.x, y: player.position.y, z: player.position.z,
    yaw: player.yaw, stance: player.stance, continuity: localContinuity,
  });

  const recoveredGuests = restoreGuestAuthorities(checkpoint, Date.now(), nowMonoMs);
  if (!recoveredGuests || recoveredGuests.length !== checkpoint.guests.length) {
    throw new Error('Stored guest authority failed strict restoration');
  }
  retainedRemoteAuthorities.clear();
  remoteHealthAuthorities.clear();
  remoteCombatInventories.clear();
  remoteCombatInventoryRevisions.clear();
  for (const guest of recoveredGuests) {
    retainedRemoteAuthorities.set(guest.snapshot.id, Object.freeze({
      snapshot: Object.freeze({ ...guest.snapshot }),
      continuity: guest.continuity,
    }));
    remoteHealthAuthorities.set(guest.snapshot.id, guest.health);
    setRemoteCombatInventory(guest.snapshot.id, guest.combatInventory);
  }

  const botStates = new Map(checkpoint.bots.map((entry) => [entry.snapshot.id, entry]));
  if (botStates.size !== bots.size) throw new Error('Stored hosted-bot roster does not match the selected match');
  for (const bot of bots.values()) {
    const stored = botStates.get(bot.id);
    if (!stored) throw new Error(`Stored hosted-bot state is missing ${bot.id}`);
    const snapshot = stored.snapshot;
    bot.name = snapshot.name;
    bot.team = snapshot.team;
    bot.position.set(snapshot.x, snapshot.y, snapshot.z);
    bot.velocity.set(stored.vx, stored.vy, stored.vz);
    bot.root.position.copy(bot.position);
    bot.root.rotation.y = snapshot.yaw;
    bot.hp = snapshot.hp;
    bot.alive = snapshot.alive;
    bot.kills = snapshot.kills;
    bot.deaths = snapshot.deaths;
    bot.weapon = snapshot.weapon;
    bot.grenade = stored.grenade;
    bot.continuity = stored.continuity;
    bot.waypoint = stored.waypoint % Math.max(1, arena.patrolPoints.length);
    bot.strafeSign = stored.strafeSign;
    bot.respawnAt = bot.alive ? 0 : nowMonoMs + recoveryRemainingMs(stored.respawnRemainingMs, checkpoint);
    bot.invulnerableUntil = nowMonoMs + recoveryRemainingMs(stored.invulnerabilityRemainingMs, checkpoint);
    bot.nextGrenadeAt = nowMonoMs + recoveryRemainingMs(stored.nextGrenadeRemainingMs, checkpoint);
    bot.grenadeActive = false;
    bot.deathVisibleUntil = 0;
    bot.stance = 'stand';
    bot.stanceHeldUntil = 0;
    bot.lastDamagedAt = Number.NEGATIVE_INFINITY;
    bot.positionHistory = [{
      at: currentHostTimeMs(), x: bot.position.x, y: bot.position.y + botStanceEyeHeightM(bot.stance), z: bot.position.z,
      yaw: bot.root.rotation.y, stance: bot.stance, continuity: bot.continuity,
    }];
    bot.perception = createBotPerceptionState(interactiveWorldMatchEpoch, bot.id, bot.continuity);
    bot.perceptionCanFire = true;
    bot.perceptionAimError = 0;
    resetOperator(bot.root);
    setOperatorWeapon(bot.root, bot.weapon, flattenOperatorMaterials, scheduleDeferredGpuRetirement);
    bot.root.visible = bot.alive;
    bot.root.userData.networkSeq = snapshot.seq;
    hostedBotStateSeq = Math.max(hostedBotStateSeq, snapshot.seq);
  }
  return player.alive ? 0 : recoveryRemainingMs(hostState.respawnRemainingMs, checkpoint);
}

function initializeFreshHostLobby(): void {
  if (pendingHostMatchRecovery?.roomCode !== network.roomCode) clearStoredHostMatchCheckpoint();
  hostMatchRecoveryPreparing = false;
  gunRangeMatchClockState = null;
  gunRangeMatchClockOccupantIds = Object.freeze([]);
  gunRangeTestBayDoorState = null;
  presentedGunRangeTestBayDoorThumpSequence = 0;
  gunRangeTestBayDoorBroadcastPending = false;
  // Remember the room code so a host who crashes can reclaim it on rehost,
  // letting guests who still have it saved rejoin the same lobby.
  saveLastHostedRoomCode(network.roomCode, clientPersistentStorage());
  // LIGHTING: the host's own solo choice seeds the lobby row rather than being
  // silently reset to the default; from here on the replicated value is the
  // authority for every peer, this host included.
  const seedTimeOfDay = privateMatchConfig.timeOfDay ?? DEFAULT_LIGHTING_TIME_CHOICE;
  privateMatchConfig = selectedArena.id === 'gun-range'
    ? { ...DEFAULT_PRIVATE_MATCH_CONFIG, arenaId: 'gun-range', mode: 'ffa', hostedBotCount: 0, autoBalance: false, durationMs: selectedArena.matchRules.durationMs ?? 120_000, timeOfDay: seedTimeOfDay }
    : { ...DEFAULT_PRIVATE_MATCH_CONFIG, arenaId: selectedArena.id, timeOfDay: seedTimeOfDay };
  privateMatchMode = privateMatchConfig.mode;
  const squad = sanitizeSquadPresentation(localSquadName, localSquadColor, player.team);
  localSquadName = squad.name;
  localSquadColor = squad.color;
  localResumeToken = randomLobbyCredential();
  hostLobbyTokens.set(player.id, localResumeToken);
  hostLobbyConnectionEpochs.set(player.id, localConnectionEpoch);
  hostLobbyMembers.set(player.id, {
    id: player.id,
    name: player.name,
    team: player.team,
    ready: false,
    connected: true,
    pingMs: 0,
    dhv: localDhv,
    squadName: localSquadName,
    squadColor: localSquadColor,
  });
  authoritativeScores.set(player.id, emptyPlayerScore(player.id));
  roomCard.hidden = false;
  roomCodeEl.textContent = network.roomCode;
  broadcastHostLobby('waiting');
  setStatus('Private lobby ready — share the invite and ready up', 'ok');
}

async function resumeRecoveredHostMatch(
  checkpoint: HostMatchCheckpoint,
  timing: HostMatchResumeTiming,
): Promise<void> {
  const result = await beginPrivateMatch(
    'host',
    timing.activeAtLocalMonoMs,
    checkpoint.activeAtEpochMs,
    performance.now(),
    checkpoint,
  );
  hostMatchRecoveryPreparing = false;
  if (!gameStarted) {
    pendingHostRecoveryJoins.clear();
    const exactReason = result.status === 'failed'
      ? result.error.message
      : result.status === 'superseded'
        ? result.reason
        : 'Match admission ended without publishing an active match';
    setStatus(`Stored match could not be restored safely: ${exactReason}. Reload to open a fresh lobby.`, 'error');
    return;
  }
  pendingHostMatchRecovery = null;
  persistActiveHostMatchCheckpoint();
  const queued = [...pendingHostRecoveryJoins.values()];
  pendingHostRecoveryJoins.clear();
  for (const message of queued) void admitLobbyJoin(message);
  setStatus(`Hosted match restored - ${Math.ceil(timing.remainingMs / 1_000)} seconds remain`, 'ok');
}

function initializeRecoveredHostLobby(checkpoint: HostMatchCheckpoint): boolean {
  const timing = resolveHostMatchResumeTiming(checkpoint);
  if (!timing || checkpoint.roomCode !== network.roomCode) return false;
  hostMatchRecoveryPreparing = true;
  pendingHostMatchRecovery = checkpoint;
  saveLastHostedRoomCode(network.roomCode, clientPersistentStorage());
  privateMatchConfig = checkpoint.config;
  privateMatchMode = checkpoint.config.mode;
  privateMatchActiveAtHostTimeMs = timing.activeAtLocalMonoMs;
  privateMatchActiveAtEpochMs = checkpoint.activeAtEpochMs;
  gunRangeMatchClockState = timing.matchClock;
  gunRangeMatchClockOccupantIds = Object.freeze([]);
  killstreakMatchEpoch = checkpoint.matchEpoch;
  privateLobbyRevision = checkpoint.lobbyRevision;
  player.id = checkpoint.hostPlayer.id;
  player.name = checkpoint.hostPlayer.name;
  player.team = checkpoint.hostPlayer.team;
  localContinuity = Math.max(0, checkpoint.hostPlayer.continuity - 1);
  element<HTMLInputElement>('#player-name').value = checkpoint.hostPlayer.name;
  element<HTMLSelectElement>('#team').value = String(checkpoint.hostPlayer.team);
  localResumeToken = randomLobbyCredential();
  hostLobbyTokens.set(player.id, localResumeToken);
  hostLobbyConnectionEpochs.set(player.id, localConnectionEpoch);
  hostLobbyMembers.clear();
  hostLobbyTokenDigests.clear();
  hostDisconnectedAt.clear();
  authoritativeScores.clear();
  const nowMonoMs = performance.now();
  const elapsedSinceSaveMs = Math.max(0, Date.now() - checkpoint.savedAtEpochMs);
  for (const member of checkpoint.members) {
    const recovered = member.id === player.id
      ? { ...member, connected: true, pingMs: 0 }
      : { ...member, connected: false, pingMs: null };
    hostLobbyMembers.set(member.id, recovered);
    network.setPlayerTeam(member.id, recovered.team);
    if (member.id !== player.id) {
      hostDisconnectedAt.set(member.id, nowMonoMs - elapsedSinceSaveMs);
      const digest = checkpoint.resumeTokenDigests.find((entry) => entry.playerId === member.id);
      if (!digest) return false;
      hostLobbyTokenDigests.set(member.id, digest);
      scheduleDisconnectedLobbyExpiry(member.id, Math.max(0, digest.expiresAtEpochMs - Date.now()));
    }
  }
  for (const score of checkpoint.scores) authoritativeScores.set(score.id, score);
  roomCard.hidden = false;
  roomCodeEl.textContent = network.roomCode;
  const phase: LobbySnapshot['phase'] = timing.phase === 'warmup' ? 'countdown' : 'active';
  privateLobbySnapshot = hostSnapshot(phase);
  network.setCapacity(checkpoint.config.capacity);
  broadcastHostLobby(phase);
  lobbyArenaSyncPromise = lobbyArenaSyncPromise
    .catch(() => undefined)
    .then(() => synchronizeLobbyArena());
  setStatus('Reclaiming the hosted match and rebuilding authoritative state...', 'warn');
  void resumeRecoveredHostMatch(checkpoint, timing);
  return true;
}

function initializeHostLobby(): void {
  if (pendingHostMatchRecovery && initializeRecoveredHostLobby(pendingHostMatchRecovery)) return;
  if (pendingHostMatchRecovery) clearStoredHostMatchCheckpoint();
  initializeFreshHostLobby();
}

function sendLobbyJoin(): void {
  if (network.role !== 'client') return;
  clientWorldRepairAdmission = null;
  pendingClientReconnectWorldRepairConnectionEpoch = null;
  clientReconnectWorldRepairAttempts = 0;
  clearClientWorldRepairTimeout();
  if (!localResumeToken) restoreRoomIdentity(network.roomCode);
  if (gameStarted || privateLobbySnapshot?.phase === 'active' || privateLobbySnapshot?.phase === 'countdown') {
    awaitingCanonicalGuestAuthority = true;
    pendingGuestResumeAuthority = null;
  } else {
    // HF-322: Joining a waiting lobby clears any armed mid-match guest authority
    awaitingCanonicalGuestAuthority = false;
    awaitingAuthoritativeRejoinContinuity = false;
    pendingGuestResumeAuthority = null;
  }
  localConnectionEpoch = randomLobbyCredential();
  pendingClientReconnectWorldRepairConnectionEpoch = awaitingCanonicalGuestAuthority
    ? localConnectionEpoch
    : null;
  localTriggerActionSequence = 0;
  transmittedTriggerHeld = false;
  transmittedTriggerWeapon = null;
  const message: LobbyJoinMessage = {
    type: 'lobby-join',
    protocolVersion: MULTIPLAYER_PROTOCOL_VERSION,
    playerId: player.id,
    connectionEpoch: localConnectionEpoch,
    name: player.name,
    requestedTeam: player.team,
    squadName: localSquadName,
    squadColor: localSquadColor,
    skinId: localOperatorSkinId, // HF-360
    stanceId: localOperatorStanceId, // HF-382
    // Build identity: the host refuses joiners whose stamped pass differs, so a
    // guest on an older channel can no longer connect cleanly and silently play
    // a different map. Optional on the wire; a joiner that omits it (a build
    // from before this field existed) is refused with 'build-mismatch' too.
    buildId: PASS66_RELEASE_IDENTITY.pass,
    resumeToken: localResumeToken,
    nonce: randomNonce(),
  };
  network.send(message);
  scheduleClockPing(0);
  renderPrivateLobby();
}

function sendClientWorldRepairReady(loadout = killstreakLoadoutController.activeMatch ?? killstreakLoadoutController.selected): void {
  if (network.role !== 'client' || !gameStarted) return;
  const repairReadyNow = performance.now();
  const admission = clientWorldRepairAdmission;
  const reconnectRepair = awaitingCanonicalGuestAuthority
    && pendingClientReconnectWorldRepairConnectionEpoch === localConnectionEpoch;
  if (!clientWorldRepairCanAttempt(admission, repairReadyNow) && !reconnectRepair) return;
  network.send({ type: 'join', player: snapshot() });
  // The reliable state commit is ordered before the loadout intent on the
  // event lane. On a rematch the host has rebuilt the remote at continuity 1;
  // this observed state advances it to the guest's current life before the
  // idempotent loadout registration validates that life.
  network.sendStateCommitReliably(createStateMessage());
  const loadoutMessage: KillstreakLoadoutIntentMessage = {
    type: 'killstreak-loadout-intent', by: player.id, matchEpoch: killstreakMatchEpoch,
    lifeId: localContinuity, sequence: 0, loadout, nonce: randomNonce(),
  };
  network.send(loadoutMessage);
  if (admission) clientWorldRepairAdmission = recordClientWorldRepairAttempt(admission, repairReadyNow);
  if (reconnectRepair) clientReconnectWorldRepairAttempts += 1;
  if (reconnectRepair) pendingClientReconnectWorldRepairConnectionEpoch = null;
}

function rejectLobbyPlayer(
  playerId: string,
  reason: 'room-full' | 'rejoin-denied' | 'match-active' | 'build-mismatch',
  provisionalResumeToken?: string,
  connectionEpoch?: string,
): void {
  if (provisionalResumeToken !== undefined && connectionEpoch !== undefined) {
    network.rejectPlayerAdmission(playerId, provisionalResumeToken, connectionEpoch, reason);
    return;
  }
  network.sendToPlayer(playerId, { type: 'lobby-reject', reason, nonce: randomNonce() });
  window.setTimeout(() => network.disconnectPlayer(playerId), 75);
}

/**
 * Rebind document-local authority domains after the resume token authenticated a
 * replacement transport. Retain the lobby identity, health, score and reward
 * bank; only transient sender state is reset. The host-owned killstreak life is
 * adopted here, never a life value claimed by the replacement document.
 */
function resetAuthenticatedGuestReplacement(playerId: string): void {
  const now = performance.now();
  hostKillstreakLoadoutAcks.clearActor(playerId);
  pendingGuestAuthorityRepairs.delete(playerId);
  clearRemoteReloadAuthority(playerId);
  const remote = remotes.get(playerId);
  if (remote) {
    remote.interpolation.clear();
    remote.positionHistory.length = 0;
    remote.awaitingReplacementState = true;
    remote.lastSeen = now;
    remote.feedbackSequenceGaps = 0;
    remote.feedbackReordered = 0;
    remote.lastFeedbackAt = Number.NEGATIVE_INFINITY;
    remote.claimEligibleAt = Math.max(remote.claimEligibleAt, now + 1_500);
    const authoritativeLifeId = killstreakRuntime.actorLifeId(playerId);
    if (authoritativeLifeId !== null) remote.continuity = authoritativeLifeId;
  }
  authoritativeShotAdmissions.delete(playerId);
  remoteShotAdmissions.delete(playerId);
  const retainedCrossbowActions = admittedRemoteShots.get(playerId);
  if (retainInFlightCrossbowGlassActions(retainedCrossbowActions, interactiveWorldMatchEpoch, now) === 0) {
    admittedRemoteShots.delete(playerId);
  }
  admittedRemoteMelees.delete(playerId);
  admittedRemoteExplosions.delete(playerId);
  remoteMeleeAdmissions.delete(playerId);
  peerTimingStates.delete(playerId);
  hostTriggerAuthorities.reset(playerId, 'connection-epoch');
  if (killstreakRegisteredActors.has(playerId)) killstreakRuntime.recordActorDisconnect(playerId);
}

function safeGuestResumeFallbackSnapshot(remote: RemotePlayer, attempt: number): PlayerSnapshot | null {
  const colliders = activeWorldColliders();
  const preferred = arena.spawns[remote.snapshot.team];
  const alternate = arena.spawns[remote.snapshot.team === 0 ? 1 : 0];
  const candidates = [...preferred, ...alternate]
    .filter((point) => Number.isFinite(point.x) && Number.isFinite(point.y) && Number.isFinite(point.z))
    .filter((point) => pointInsideBounds(point, arena.bounds, 0.44) && !isBlocked(point, colliders, 0.44));
  if (candidates.length === 0) return null;
  const occupants = [...remotes.values()]
    .filter((candidate) => candidate.snapshot.id !== remote.snapshot.id && candidate.snapshot.hp > 0)
    .map((candidate) => new THREE.Vector3(candidate.snapshot.x, candidate.snapshot.y, candidate.snapshot.z));
  const ranked = candidates.map((point, index) => ({
    point,
    index,
    clearance: occupants.length === 0
      ? Number.POSITIVE_INFINITY
      : Math.min(...occupants.map((occupant) => occupant.distanceToSquared(point))),
  })).sort((left, right) => right.clearance - left.clearance || left.index - right.index);
  const selected = ranked[Math.min(ranked.length - 1, Math.max(0, attempt - 1))]!.point;
  return Object.freeze({
    ...remote.snapshot,
    x: selected.x,
    y: selected.y,
    z: selected.z,
    stance: 'stand',
  });
}

function sendGuestResumeAuthority(playerId: string, remote: RemotePlayer): boolean {
  if (network.role !== 'host' || !gameStarted || !remote.awaitingReplacementState) return false;
  const connectionEpoch = hostLobbyConnectionEpochs.get(playerId);
  const pending = pendingGuestAuthorityRepairs.get(playerId);
  if (connectionEpoch && pending?.connectionEpoch === connectionEpoch) {
    network.sendToPlayer(playerId, pending.message);
    sendCarpetGroundFirePresentationSnapshot(playerId);
    return true;
  }
  const member = hostLobbyMembers.get(playerId);
  const score = authoritativeScores.get(playerId);
  const actor = killstreakRuntime.snapshotFor(playerId, performance.now()).actors.find((entry) => entry.actorId === playerId);
  const priorHealth = remoteHealthAuthorities.get(playerId);
  const combatInventory = remoteCombatInventories.get(playerId);
  if (!connectionEpoch || !member || !score || !actor || !priorHealth || !combatInventory) return false;
  const now = performance.now();
  const health = advanceRemoteHealthAuthority(priorHealth, now);
  const canonical = canonicalRetainedGuestSnapshot(remote.snapshot, member, score, health);
  remote.snapshot = canonical;
  remote.continuity = actor.lifeId;
  remoteHealthAuthorities.set(playerId, health);
  retainedRemoteAuthorities.set(playerId, Object.freeze({
    snapshot: Object.freeze({ ...canonical }),
    continuity: actor.lifeId,
  }));
  const authorityNonce = randomNonce();
  const message: GuestResumeAuthorityMessage = {
    type: 'guest-resume-authority',
    protocolVersion: MULTIPLAYER_PROTOCOL_VERSION,
    by: player.id,
    forPlayerId: playerId,
    connectionEpoch,
    matchEpoch: killstreakMatchEpoch,
    worldRevision: interactiveWorldRuntime?.collisions().revision ?? 0,
    attempt: 0,
    placementReason: 'retained',
    player: canonical,
    combatInventory,
    combatInventoryRevision: Math.max(0, remoteCombatInventoryRevisions.get(playerId) ?? 0),
    continuity: actor.lifeId,
    respawnRemainingMs: health.alive ? 0 : Math.max(1, Math.min(10_000, health.respawnEligibleAt - now)),
    loadout: actor.loadout,
    nonce: authorityNonce,
  };
  pendingGuestAuthorityRepairs.set(playerId, Object.freeze({ connectionEpoch, authorityNonce, message }));
  network.sendToPlayer(playerId, message);
  sendCarpetGroundFirePresentationSnapshot(playerId, now);
  return true;
}

function acceptGuestResumeAck(message: GuestResumeAckMessage): boolean {
  if (message.type !== 'guest-resume-ack') return false;
  if (network.role !== 'host' || processedNonces.has(message.nonce)) return true;
  const pending = pendingGuestAuthorityRepairs.get(message.by);
  if (!pending || !admitGuestResumeAck(message, {
    expectedPlayerId: message.by,
    expectedConnectionEpoch: pending.connectionEpoch,
    expectedMatchEpoch: killstreakMatchEpoch,
    expectedAuthorityNonce: pending.authorityNonce,
  }) || hostLobbyConnectionEpochs.get(message.by) !== message.connectionEpoch) return true;
  const remote = remotes.get(message.by);
  if (!remote || !remote.awaitingReplacementState) return true;
  processedNonces.add(message.nonce);
  // The replacement document may have emitted a state-lane sample before its
  // reliable world-ready join. Only this exact epoch + authority-nonce ACK
  // releases mutable pose authority; earlier samples must not replace the
  // retained host pose used by the resume transaction.
  remote.awaitingReplacementState = false;
  pendingGuestAuthorityRepairs.delete(message.by);
  const member = hostLobbyMembers.get(message.by);
  if (member && !member.connected) {
    // This ACK can only arrive on the current admitted event connection and is
    // bound to the exact replacement connection epoch and authority nonce. It
    // therefore supersedes a late disconnect notification from the retired
    // document and is the strongest available lobby-liveness observation.
    hostDisconnectedAt.delete(message.by);
    hostLobbyMembers.set(message.by, { ...member, connected: true });
    broadcastHostLobby(privateLobbySnapshot?.phase ?? 'active');
  }
  trimNonceSet();
  return true;
}

function sendGuestResumeFailure(
  pending: GuestResumeAuthorityMessage,
  reason: GuestResumeFailureMessage['reason'],
): void {
  const failure: GuestResumeFailureMessage = {
    type: 'guest-resume-failure', protocolVersion: MULTIPLAYER_PROTOCOL_VERSION,
    by: player.id, forPlayerId: pending.forPlayerId,
    connectionEpoch: pending.connectionEpoch, matchEpoch: pending.matchEpoch,
    worldRevision: pending.worldRevision, authorityNonce: pending.nonce,
    attempt: pending.attempt, reason, nonce: randomNonce(),
  };
  pendingGuestAuthorityRepairs.delete(pending.forPlayerId);
  network.sendToPlayer(pending.forPlayerId, failure);
}

function acceptGuestResumeNack(message: GuestResumeNackMessage): boolean {
  if (message.type !== 'guest-resume-nack') return false;
  if (network.role !== 'host' || processedNonces.has(message.nonce)) return true;
  const pendingRecord = pendingGuestAuthorityRepairs.get(message.by);
  const pending = pendingRecord?.message;
  if (!pending || !admitGuestResumeNack(message, pending, message.by)
    || hostLobbyConnectionEpochs.get(message.by) !== message.connectionEpoch) return true;
  processedNonces.add(message.nonce);
  trimNonceSet();
  if (!guestResumeRetryAllowed(pending.attempt)) {
    sendGuestResumeFailure(pending, 'retry-ceiling');
    return true;
  }
  const remote = remotes.get(message.by);
  if (!remote) {
    sendGuestResumeFailure(pending, 'no-safe-pose');
    return true;
  }
  const attempt = pending.attempt + 1;
  const fallback = safeGuestResumeFallbackSnapshot(remote, attempt);
  if (!fallback) {
    sendGuestResumeFailure(pending, 'no-safe-pose');
    return true;
  }
  remote.snapshot = fallback;
  retainedRemoteAuthorities.set(message.by, Object.freeze({
    snapshot: Object.freeze({ ...fallback }),
    continuity: pending.continuity,
  }));
  broadcastInteractiveWorldState(true);
  const retry: GuestResumeAuthorityMessage = {
    ...pending,
    worldRevision: interactiveWorldRuntime?.collisions().revision ?? pending.worldRevision,
    attempt,
    placementReason: 'safe-fallback',
    player: fallback,
    nonce: randomNonce(),
  };
  pendingGuestAuthorityRepairs.set(message.by, Object.freeze({
    connectionEpoch: retry.connectionEpoch,
    authorityNonce: retry.nonce,
    message: retry,
  }));
  persistActiveHostMatchCheckpoint();
  network.sendToPlayer(message.by, retry);
  return true;
}

// HF-322: Bounded timeout and failure handlers for client world repair and resume authority
function clearClientWorldRepairTimeout(): void {
  if (pendingClientWorldRepairTimeout !== null) window.clearTimeout(pendingClientWorldRepairTimeout);
  pendingClientWorldRepairTimeout = null;
}

function handleClientWorldRepairFailure(reason = 'admission-unacknowledged'): void {
  if (network.role !== 'client') return;
  // Lane J: this call kills the local player and tells them to rejoin, so it
  // must be able to justify itself after the fact. Record the exact clock the
  // deadline judged on.
  clientWorldRepairFailureTelemetry.total += 1;
  clientWorldRepairFailureTelemetry.last = {
    reason,
    atMs: Math.round(performance.now()),
    hostContactAtMs: hostMatchContactAtMs === null ? null : Math.round(hostMatchContactAtMs),
    attempts: clientWorldRepairAdmission?.attempts ?? null,
    lastAttemptAtMs: clientWorldRepairAdmission?.lastAttemptAtMs === null
      || clientWorldRepairAdmission?.lastAttemptAtMs === undefined
      ? null
      : Math.round(clientWorldRepairAdmission.lastAttemptAtMs),
    lifeId: clientWorldRepairAdmission?.identity.lifeId ?? null,
    localContinuity,
    gameStarted,
    matchPhase: matchState.phase,
  };
  clearClientWorldRepairTimeout();
  clientWorldRepairAdmission = null;
  pendingClientReconnectWorldRepairConnectionEpoch = null;
  clientReconnectWorldRepairAttempts = 0;
  player.hp = 0;
  player.alive = false;
  clearGameplayInput();
  weaponView.setPresentationVisible(false);
  setStatus(`Match admission unacknowledged by host (${reason}). Rejoin to retry.`, 'error');
  addFeed('MATCH ADMISSION FAILED · RETRY FROM LOBBY');
}

function handleGuestResumeTimeout(): void {
  if (network.role !== 'client' || !awaitingCanonicalGuestAuthority) return;
  clearGuestResumeTimeout();
  clearClientWorldRepairTimeout();
  clientWorldRepairAdmission = null;
  pendingGuestResumeAuthority = null;
  awaitingCanonicalGuestAuthority = false;
  awaitingAuthoritativeRejoinContinuity = false;
  pendingClientReconnectWorldRepairConnectionEpoch = null;
  clientReconnectWorldRepairAttempts = 0;
  player.hp = 0;
  player.alive = false;
  clearGameplayInput();
  weaponView.setPresentationVisible(false);
  setStatus('Match resume authority timed out. Rejoin to retry.', 'error');
  addFeed('REJOIN AUTHORITY TIMEOUT · RETRY FROM LOBBY');
}

function scheduleClientWorldRepairTimeout(epoch: string, matchEpoch: number): void {
  clearClientWorldRepairTimeout();
  // HF-347 residual (Lane J, "cant move alot in host and guest lobby" / "cant
  // mov when spawn into rustrig"): this deadline used to be a single 5s timer
  // armed at lobby-start, racing BOTH sides' arena load and the WebGL
  // first-presentation prime (which pauses the state pump via
  // matchAdmissionPresentationPaused). Heavy arenas lost that race, the guest
  // was declared dead at spawn and never recovered — reproduced 4/6 arenas by
  // scripts/qa/verify-hf347-arena-movement-matrix.mjs under load. The 5s bound
  // is unchanged but now measures HANDSHAKE inactivity while this client can
  // actually transact, under an absolute arming cap; the rule itself lives in
  // client-world-repair-admission.ts (evaluateClientWorldRepairDeadline) with
  // its own unit tests. The old code also silently dropped the timer when the
  // callback fired before gameStarted, leaving no deadline at all — the
  // cadence re-check closes that hole too.
  const armedAtMs = performance.now();
  let pumpEligibleSinceMs: number | null = null;
  // Lane J: first contact from the host in THIS match. Until it lands, the
  // host is simply still loading its own arena and the inactivity clock has
  // nothing to measure — see hostContactAtMs in client-world-repair-admission.
  hostMatchContactAtMs = null;
  const checkClientWorldRepairDeadline = (): void => {
    pendingClientWorldRepairTimeout = null;
    if (network.role !== 'client' || matchEpoch !== killstreakMatchEpoch || epoch !== localConnectionEpoch) return;
    const admissionPending = clientWorldRepairAdmission !== null && !clientWorldRepairAdmission.acknowledged;
    if (!admissionPending && !awaitingCanonicalGuestAuthority) return;
    const nowMs = performance.now();
    if (gameStarted && !matchAdmissionPresentationPaused) {
      if (pumpEligibleSinceMs === null) pumpEligibleSinceMs = nowMs;
    } else {
      pumpEligibleSinceMs = null;
    }
    // Lane J residual: the repair-ready retry used to be spendable ONLY by an
    // incoming host killstreak-state snapshot. Forensics (this machine): host
    // contact 19059 ms, admission failure 24614 ms, attempts frozen at 1 of 2
    // - the guest died at spawn holding an unused retry, then auto-respawned
    // and left a permanent status line accusing a healthy host. Spend the held
    // retry here too: clientWorldRepairReceiverReady enforces the SAME pure
    // gate as the snapshot path (attempt cap, >=1s spacing, unacknowledged,
    // current epochs), and sendClientWorldRepairReady re-checks gameStarted.
    // It is fenced by pump eligibility so it never fires while loading or
    // during the presentation prime, and it runs BEFORE the deadline judgement
    // below so a spent attempt registers as handshake progress per the module's
    // documented rule. No bound is weakened: HANDSHAKE_TIMEOUT_MS,
    // ARMING_CAP_MS, MAX_CLIENT_WORLD_REPAIR_ATTEMPTS and MIN_SPACING are all
    // unchanged. The resume path (admission null) is excluded by the gate.
    //
    // Pass 79 residual (farcrysis lane, run-4 forensics: attempt #2 spent at
    // 16224 ms, first host contact 18316 ms, 'attempts-exhausted' declared at
    // 18439 ms): WITHOUT a contact fence the timer burned BOTH retries ~1s
    // after match start while the heavy-arena host was still transacting
    // nothing, so the healthy host's first snapshot could only declare
    // exhaustion instead of finding an attempt in flight. A repair attempt is
    // a request TO the host; pre-contact silence is already bounded by
    // ARMING_CAP_MS (evaluateClientWorldRepairDeadline refuses to judge
    // inactivity before hostContactAtMs for exactly this reason). Requiring
    // first host contact here means the held retry lands just AFTER contact,
    // registers fresh progress, and forces the acknowledging killstreak-state
    // via the host join handler (broadcastKillstreakState(force)) - which is
    // what actually completes the handshake.
    if (pumpEligibleSinceMs !== null
      && hostMatchContactAtMs !== null
      && clientWorldRepairReceiverReady(clientWorldRepairAdmission, {
        connectionEpoch: epoch,
        matchEpoch,
        exactActorAcknowledged: false,
      }, nowMs)) {
      sendClientWorldRepairReady();
    }
    // The resume path judges the same inactivity rule; it has no admission
    // record, so judge a fresh unacknowledged one (progress = eligibility).
    const judged = clientWorldRepairAdmission ?? beginClientWorldRepair({
      playerId: player.id,
      connectionEpoch: epoch,
      matchEpoch,
      lifeId: Math.max(0, localContinuity),
    });
    const repairRuling = evaluateClientWorldRepairDeadline({
      nowMs, armedAtMs, pumpEligibleSinceMs, hostContactAtMs: hostMatchContactAtMs, admission: judged,
    });
    if (repairRuling === 'failed') {
      if (admissionPending) handleClientWorldRepairFailure('admission-timeout');
      else handleGuestResumeTimeout();
      return;
    }
    pendingClientWorldRepairTimeout = window.setTimeout(
      checkClientWorldRepairDeadline,
      CLIENT_WORLD_REPAIR_DEADLINE_CHECK_INTERVAL_MS,
    );
  };
  pendingClientWorldRepairTimeout = window.setTimeout(
    checkClientWorldRepairDeadline,
    CLIENT_WORLD_REPAIR_DEADLINE_CHECK_INTERVAL_MS,
  );
}

function clearGuestResumeTimeout(): void {
  if (pendingGuestResumeTimeout !== null) window.clearTimeout(pendingGuestResumeTimeout);
  pendingGuestResumeTimeout = null;
}

function nackGuestResumeAuthority(
  message: GuestResumeAuthorityMessage,
  reason: GuestResumeNackMessage['reason'],
): void {
  if (network.role !== 'client' || message.nonce === lastGuestResumeNackNonce) return;
  clearGuestResumeTimeout();
  lastGuestResumeNackNonce = message.nonce;
  const nack: GuestResumeNackMessage = {
    type: 'guest-resume-nack', protocolVersion: MULTIPLAYER_PROTOCOL_VERSION,
    by: player.id, connectionEpoch: localConnectionEpoch, matchEpoch: message.matchEpoch,
    worldRevision: message.worldRevision, authorityNonce: message.nonce,
    attempt: message.attempt, reason, nonce: randomNonce(),
  };
  network.send(nack);
}

function scheduleGuestResumeWorldTimeout(message: GuestResumeAuthorityMessage): void {
  clearGuestResumeTimeout();
  pendingGuestResumeTimeout = window.setTimeout(() => {
    pendingGuestResumeTimeout = null;
    if (pendingGuestResumeAuthority?.nonce !== message.nonce || !awaitingCanonicalGuestAuthority) return;
    nackGuestResumeAuthority(message, 'world-repair-timeout');
  }, 2_500);
}

function acceptGuestResumeFailure(message: GuestResumeFailureMessage): boolean {
  if (message.type !== 'guest-resume-failure') return false;
  const pending = pendingGuestResumeAuthority;
  if (network.role !== 'client' || !pending || message.by !== privateLobbySnapshot?.hostId
    || message.forPlayerId !== player.id || message.connectionEpoch !== localConnectionEpoch
    || message.matchEpoch !== pending.matchEpoch || message.worldRevision !== pending.worldRevision
    || message.authorityNonce !== pending.nonce || message.attempt !== pending.attempt) return true;
  clearGuestResumeTimeout();
  clearClientWorldRepairTimeout();
  pendingGuestResumeAuthority = null;
  awaitingCanonicalGuestAuthority = false;
  awaitingAuthoritativeRejoinContinuity = false;
  player.hp = 0;
  player.alive = false;
  clearGameplayInput();
  weaponView.setPresentationVisible(false);
  setStatus(`Canonical rejoin failed (${message.reason}). Use Rejoin to retry safely.`, 'error');
  addFeed('REJOIN AUTHORITY FAILED · RETRY FROM LOBBY');
  return true;
}

function applyGuestResumeAuthority(message: GuestResumeAuthorityMessage): boolean {
  if (message.type !== 'guest-resume-authority') return false;
  if (network.role !== 'client' || !gameStarted || !awaitingCanonicalGuestAuthority) return true;
  const admission = admitGuestResumeAuthority(message, {
    expectedHostId: privateLobbySnapshot?.hostId ?? null,
    expectedPlayerId: player.id,
    expectedConnectionEpoch: localConnectionEpoch,
    expectedMatchEpoch: killstreakMatchEpoch,
    seenNonces: processedNonces,
  });
  if (!admission.accepted) return true;
  if (pendingGuestResumeAuthority?.nonce !== message.nonce) lastGuestResumeNackNonce = null;
  pendingGuestResumeAuthority = message;
  const appliedWorldRevision = interactiveWorldRuntime?.collisions().revision ?? null;
  if (!guestResumeWorldRevisionReady(appliedWorldRevision, message.worldRevision)) {
    scheduleGuestResumeWorldTimeout(message);
    return true;
  }
  clearGuestResumeTimeout();
  const projection = guestResumeProjection(message);
  const canonical = projection.player;
  const stance = canonical.stance ?? 'stand';
  // MP-LAB: the same family as the state-admission drop fixed earlier in this
  // lane, on the path that decides whether a resuming guest may stand where the
  // host says it stands. At 0.44 the bounds half rejects the resting pose of
  // EVERY stance against a perimeter wall (stand rests at maxX - 0.38,
  // crouch/prone at maxX - 0.36; all three measured rejected at 0.44 and
  // admitted at the admission margin by scripts/qa/mp-lab/resting-pose-admission.mts),
  // so a guest that reconnects while hugging a wall NACKs 'blocked-pose' and
  // spends its resume retries on a legal position. The world question is the
  // one state admission asks; the collider question keeps the mover's own
  // 0.44 m radius, unchanged.
  if (!pointInsideBounds(canonical, arena.bounds, STATE_ADMISSION_BOUNDS_MARGIN) || isBlocked(canonical, activeWorldColliders(), 0.44)) {
    nackGuestResumeAuthority(message, 'blocked-pose');
    return true;
  }
  if (characterPhysics && !characterPhysics.setStance(stance)) {
    nackGuestResumeAuthority(message, 'stance-rejected');
    return true;
  }

  applyingLocalReloadAuthority = true;
  interruptReload(true);
  applyingLocalReloadAuthority = false;
  clearGameplayInput();
  player.name = canonical.name;
  player.team = canonical.team;
  player.position.set(canonical.x, canonical.y, canonical.z);
  player.velocity.set(0, 0, 0);
  player.yaw = canonical.yaw;
  player.pitch = canonical.pitch;
  player.hp = canonical.hp;
  player.alive = canonical.hp > 0;
  player.kills = canonical.kills;
  player.deaths = canonical.deaths;
  player.primaryWeapon = canonical.primary;
  player.secondaryWeapon = canonical.secondary;
  player.selectedGrenade = canonical.grenade;
  player.weapon = canonical.weapon;
  player.stance = stance;
  // HF-412: an authority restore is a teleport, not a player-initiated stance
  // change. Drop any drop-shot transition still in flight so the rendered eye
  // does not keep an offset from a pose this player no longer has.
  stanceTransition = null;
  stanceTransitionSample = restingStanceTransitionSample(player.stance);
  player.seq = Math.max(player.seq, canonical.seq);
  for (const weapon of ORDINARY_WEAPON_IDS) {
    player.ammo[weapon] = projection.combatInventory.ammo[weapon];
    player.reserve[weapon] = projection.combatInventory.reserve[weapon];
  }
  player.grenades = projection.combatInventory.grenades;
  lastAppliedLocalCombatAuthorityRevision = projection.combatInventoryRevision;
  lastAppliedLocalShotResultSeq = -1;
  pendingLocalOrdinaryShots.clear();
  pendingLocalReloadAuthority = null;
  pendingLocalPickup = null;
  localReloadActionSequence.reset();
  player.invulnerableUntil = 0;
  localContinuity = projection.continuity;
  localHostConfirmedContinuity = projection.continuity;
  killstreakLoadoutController.reconcileActiveMatchAuthority(projection.loadout);
  gamepadSupportSelection = projection.loadout.slots[0];
  syncFieldSupportRows(projection.loadout);
  localPositionHistory.length = 0;
  localCombatEventSeq = 0;
  localTriggerActionSequence = 0;
  transmittedTriggerHeld = false;
  transmittedTriggerWeapon = null;
  resetFlashVictimLife();
  characterPhysics?.teleportEye(player.position);
  camera.position.copy(player.position);
  camera.rotation.set(player.pitch, player.yaw, 0, 'YXZ');
  camera.updateMatrixWorld(true);
  weaponView.setWeapon(player.weapon, true);
  weaponView.setPresentationVisible(player.alive);
  if (!player.alive) scheduleLocalRespawn(performance.now(), projection.respawnRemainingMs);
  renderFieldKitSelection();
  updateFieldSupportHud();
  lastAppliedGuestResumeAuthority = Object.freeze({
    authorityNonce: message.nonce,
    connectionEpoch: message.connectionEpoch,
    appliedAtMonoMs: performance.now(),
    hp: canonical.hp,
    position: Object.freeze([canonical.x, canonical.y, canonical.z] as const),
    primary: canonical.primary,
    secondary: canonical.secondary,
    grenade: canonical.grenade,
    weapon: canonical.weapon,
    combatInventory: projection.combatInventory,
    continuity: projection.continuity,
  });
  processedNonces.add(message.nonce);
  clearGuestResumeTimeout();
  clearClientWorldRepairTimeout();
  pendingGuestResumeAuthority = null;
  lastGuestResumeNackNonce = null;
  awaitingCanonicalGuestAuthority = false;
  awaitingAuthoritativeRejoinContinuity = false;
  if (network.roomCode && localResumeToken) {
    try { saveActiveRoomIdentity(network.roomCode); } catch { /* In-memory authority remains canonical. */ }
  }
  const ack: GuestResumeAckMessage = {
    type: 'guest-resume-ack',
    protocolVersion: MULTIPLAYER_PROTOCOL_VERSION,
    by: player.id,
    connectionEpoch: localConnectionEpoch,
    matchEpoch: killstreakMatchEpoch,
    authorityNonce: message.nonce,
    nonce: randomNonce(),
  };
  network.send(ack);
  network.sendStateCommitReliably(createStateMessage());
  trimNonceSet();
  return true;
}

async function admitLobbyJoin(message: LobbyJoinMessage): Promise<void> {
  if (network.role !== 'host') return;
  if (hostMatchRecoveryPreparing) {
    pendingHostRecoveryJoins.set(message.playerId, message);
    return;
  }
  const inFlight = hostLobbyAdmissionInFlight.get(message.playerId);
  if (inFlight) {
    if (inFlight.connectionEpoch !== message.connectionEpoch) pendingHostRecoveryJoins.set(message.playerId, message);
    return;
  }
  const attempt: HostLobbyAdmissionAttempt = Object.freeze({
    generation: hostLobbySessionGeneration,
    playerId: message.playerId,
    connectionEpoch: message.connectionEpoch,
  });
  hostLobbyAdmissionInFlight.set(message.playerId, attempt);
  // HF-323: re-render lobby immediately so host sees PLAYER JOINING... and START is held
  renderPrivateLobby();
  try {
    const existing = hostLobbyMembers.get(message.playerId);
    const joiningNewMember = existing === undefined;
    const currentPhase = privateLobbySnapshot?.phase ?? 'waiting';
    if (existing) {
      let credentialAccepted = hostLobbyTokens.get(message.playerId) === message.resumeToken;
      const digest = hostLobbyTokenDigests.get(message.playerId);
      if (!credentialAccepted && digest && digest.expiresAtEpochMs > Date.now()) {
        credentialAccepted = await resumeTokenMatchesDigest(message.resumeToken, digest.sha256);
      }
      if (!hostLobbyAdmissionAttemptCurrent(attempt)) return;
      if (!credentialAccepted) {
        rejectLobbyPlayer(message.playerId, 'rejoin-denied', message.resumeToken, message.connectionEpoch);
        return;
      }
      await rememberHostLobbyResumeTokenDigest(message.playerId, message.resumeToken, attempt);
      if (!hostLobbyAdmissionAttemptCurrent(attempt)) return;
      if (!network.confirmPlayerAdmission(message.playerId, message.resumeToken, message.connectionEpoch)) return;
      hostLobbyTokens.set(message.playerId, message.resumeToken);
      hostDisconnectedAt.delete(message.playerId);
      const priorConnectionEpoch = hostLobbyConnectionEpochs.get(message.playerId);
      hostLobbyConnectionEpochs.set(message.playerId, message.connectionEpoch);
      if (priorConnectionEpoch !== message.connectionEpoch) {
        resetAuthenticatedGuestReplacement(message.playerId);
      }
      const restored = { ...existing, name: message.name, connected: true, pingMs: message.playerId === player.id ? 0 : existing.pingMs };
      hostLobbyMembers.set(message.playerId, restored);
      network.setPlayerTeam(message.playerId, restored.team);
    } else {
      // HF-323: reject new join with 'match-active' ONLY during phase 'active'. Phase 'countdown' is admitted.
      if (currentPhase === 'active') {
        rejectLobbyPlayer(message.playerId, 'match-active', message.resumeToken, message.connectionEpoch);
        return;
      }
      if (currentPhase !== 'waiting' && currentPhase !== 'countdown') {
        return;
      }
      if (hostLobbyMembers.size >= privateMatchConfig.capacity) {
        rejectLobbyPlayer(message.playerId, 'room-full', message.resumeToken, message.connectionEpoch);
        return;
      }
      // Build identity: a joiner stamped for a different pass (or a build too
      // old to stamp one) would be admitted into a lobby whose arena, weapons
      // and protocol vocabulary it does not share, and would silently play a
      // different map from the host. Refuse with the reason the joiner's UI
      // can name before any membership state is mutated.
      if (message.buildId !== PASS66_RELEASE_IDENTITY.pass) {
        rejectLobbyPlayer(message.playerId, 'build-mismatch', message.resumeToken, message.connectionEpoch);
        return;
      }
      await rememberHostLobbyResumeTokenDigest(message.playerId, message.resumeToken, attempt);
      if (!hostLobbyAdmissionAttemptCurrent(attempt)) return;
      if (!network.confirmPlayerAdmission(message.playerId, message.resumeToken, message.connectionEpoch)) return;
      hostLobbyTokens.set(message.playerId, message.resumeToken);
      hostLobbyConnectionEpochs.set(message.playerId, message.connectionEpoch);
      authoritativeShotAdmissions.delete(message.playerId);
      hostTriggerAuthorities.reset(message.playerId, 'connection-epoch');
      const squad = sanitizeSquadPresentation(message.squadName, message.squadColor, message.requestedTeam);
      // HF-360: adopt a valid joiner skin preference and start its asset load.
      const joinSkinId = isSelectableOperatorSkinId(message.skinId) ? message.skinId : undefined;
      if (joinSkinId) void loadOperatorSkinAsset(joinSkinId);
      hostLobbyMembers.set(message.playerId, {
        id: message.playerId,
        name: message.name,
        team: message.requestedTeam,
        ready: currentPhase === 'countdown',
        connected: true,
        pingMs: null,
        dhv: 10,
        squadName: squad.name,
        squadColor: squad.color,
        ...(joinSkinId ? { skinId: joinSkinId } : {}),
        ...(isOperatorStanceId(message.stanceId) ? { stanceId: message.stanceId } : {}),
      });
      authoritativeScores.set(message.playerId, emptyPlayerScore(message.playerId));
    }
    // Reconnecting an existing identity does not change lobby composition or
    // teams, so it must not clear everybody else's readiness.
    // HF-328: in TDM a joiner is prescribed onto the smaller side and the whole
    // roster is re-stamped with canonical identities. This no longer depends on the
    // autoBalance toggle - prescription is the rule, not an option.
    //
    // Countdown joiners are prescribed too (HF-323 admits them during the
    // lead-in): the waiting-only guard let every countdown joiner keep their
    // self-picked team - and the guest JOIN default is team 1 - so late
    // joiners all stacked CORAL, violating the very contract this block
    // enforces. During countdown, only the JOINER is placed (onto the smaller
    // side); already-ready members keep their teams and their readiness -
    // re-stamping the whole roster mid-countdown would un-ready everyone.
    if (joiningNewMember && privateMatchConfig.mode !== 'ffa') {
      if (currentPhase === 'waiting') {
        for (const member of prescribeTeams([...hostLobbyMembers.values()])) {
          hostLobbyMembers.set(member.id, { ...member, ready: false });
        }
      } else if (currentPhase === 'countdown') {
        const roster = [...hostLobbyMembers.values()];
        const aquaCount = roster.filter((member) => member.id !== message.playerId && member.team === 0).length;
        const coralCount = roster.filter((member) => member.id !== message.playerId && member.team === 1).length;
        const joiner = hostLobbyMembers.get(message.playerId);
        if (joiner) {
          hostLobbyMembers.set(joiner.id, { ...joiner, team: aquaCount <= coralCount ? 0 : 1 });
        }
      }
    }
    // This lobby envelope establishes the host identity, arena and active match
    // epoch. A reconnecting client must finish beginPrivateMatch() before any
    // world repair is sent; its normal post-admission `join` message is that
    // readiness handshake (handled in onNetworkMessage below).
    broadcastHostLobby(currentPhase);
    if (gameStarted) sendKillstreakStateToPlayer(message.playerId, performance.now(), true);
    sendTextChatHistory(message.playerId);
    if (privateMatchActiveAtHostTimeMs !== null && privateMatchActiveAtEpochMs !== null && currentPhase !== 'waiting') {
      network.sendToPlayer(message.playerId, {
        type: 'lobby-start', by: player.id, activeAtHostTimeMs: privateMatchActiveAtHostTimeMs,
        activeAtEpochMs: privateMatchActiveAtEpochMs, hostSentTimeMs: performance.now(),
        revision: privateLobbyRevision, nonce: randomNonce(),
      });
      sendAuthoritativeScores(message.playerId);
    }
  } finally {
    if (hostLobbyAdmissionInFlight.get(message.playerId) === attempt) {
      hostLobbyAdmissionInFlight.delete(message.playerId);
      if (hostLobbySessionGeneration === attempt.generation) {
        const queued = pendingHostRecoveryJoins.get(message.playerId);
        if (queued && !hostMatchRecoveryPreparing) {
          pendingHostRecoveryJoins.delete(message.playerId);
          void admitLobbyJoin(queued);
        }
      }
      // HF-323: re-render lobby UI once admission attempt completes
      renderPrivateLobby();
    }
  }
}

function updateHostReady(message: LobbyReadyMessage): void {
  if (network.role !== 'host' || (privateLobbySnapshot?.phase ?? 'waiting') !== 'waiting') return;
  const member = hostLobbyMembers.get(message.by);
  if (!member?.connected) return;
  hostLobbyMembers.set(message.by, { ...member, ready: message.ready });
  broadcastHostLobby('waiting');
}

function updateHostTeam(message: LobbyTeamMessage): void {
  if (network.role !== 'host') return;
  // HF-328: teams are prescribed, not picked. A team message is now a SWAP SIDES
  // REQUEST, and the host is the sole authority on whether it is legal - previously
  // the requested team was written verbatim, so a client could author its own side.
  // A refused swap is silently ignored rather than partially applied.
  const members = [...hostLobbyMembers.values()];
  const swap = applyTeamSwap(
    members,
    message.by,
    message.team,
    privateLobbySnapshot?.phase ?? 'waiting',
    privateMatchConfig.mode,
  );
  if (!swap.accepted) return;
  for (const member of swap.members) hostLobbyMembers.set(member.id, member);
  broadcastHostLobby('waiting');
}

function updateHostHandicap(message: LobbyHandicapMessage): void {
  if (network.role !== 'host' || (privateLobbySnapshot?.phase ?? 'waiting') !== 'waiting') return;
  const member = hostLobbyMembers.get(message.by);
  if (!member?.connected) return;
  hostLobbyMembers.set(message.by, { ...member, dhv: message.dhv, ready: false });
  if (message.by === player.id) localDhv = message.dhv;
  broadcastHostLobby('waiting');
}

function updateHostSquad(message: LobbySquadMessage): void {
  if (network.role !== 'host') return;
  const phase = privateLobbySnapshot?.phase ?? 'waiting';
  if (phase !== 'waiting' && phase !== 'countdown' && phase !== 'active') return;
  const member = hostLobbyMembers.get(message.by);
  if (!member?.connected) return;
  const squad = sanitizeSquadPresentation(message.squadName, message.squadColor, member.team);
  hostLobbyMembers.set(message.by, {
    ...member,
    squadName: squad.name,
    squadColor: squad.color,
    ...(phase === 'waiting' ? { ready: false } : {}),
  });
  if (message.by === player.id) {
    localSquadName = squad.name;
    localSquadColor = squad.color;
  }
  broadcastHostLobby(phase);
}

/** HF-360: host-authoritative skin adoption, mirroring updateHostSquad. A
 * cosmetic choice never clears anybody's readiness. */
function updateHostSkin(message: LobbySkinMessage): void {
  if (network.role !== 'host') return;
  const phase = privateLobbySnapshot?.phase ?? 'waiting';
  if (phase !== 'waiting' && phase !== 'countdown' && phase !== 'active') return;
  const member = hostLobbyMembers.get(message.by);
  if (!member?.connected || !isSelectableOperatorSkinId(message.skinId)) return;
  hostLobbyMembers.set(message.by, { ...member, skinId: message.skinId });
  void loadOperatorSkinAsset(message.skinId);
  broadcastHostLobby(phase);
}

/** HF-360: the replicated skin for a peer's third-person presentation. Falls
 * back to the retained default operator for anything absent or off-catalog. */
function updateHostStance(message: LobbyStanceMessage): void {
  if (network.role !== 'host') return;
  const phase = privateLobbySnapshot?.phase ?? 'waiting';
  if (phase !== 'waiting' && phase !== 'countdown' && phase !== 'active') return;
  const member = hostLobbyMembers.get(message.by);
  if (!member?.connected || !isOperatorStanceId(message.stanceId)) return;
  hostLobbyMembers.set(message.by, { ...member, stanceId: message.stanceId });
  broadcastHostLobby(phase);
  syncRemoteOperatorStances();
}

const EMOTE_LOCAL_COOLDOWN_MS = 1_500;
let lastEmoteSentAt = 0;

/** The EMOTE key. The selector chose a gesture since Pass 75; this makes the key
 * exist. Local player is first-person, so the payoff is entirely on OTHER
 * screens: the message relays host-authoritatively and every peer plays the
 * one-shot on this player's remote rig. Locally you get the feed line. */
function performEmote(): void {
  if (!gameStarted || !player.alive) return;
  const emoteId = localOperatorEmoteId;
  if (!isOperatorEmoteId(emoteId) || emoteId === 'none') {
    addFeed('NO EMOTE BOUND - PICK ONE IN OPERATOR', 'gold');
    return;
  }
  const now = performance.now();
  if (now - lastEmoteSentAt < EMOTE_LOCAL_COOLDOWN_MS) return;
  lastEmoteSentAt = now;
  const message: EmoteMessage = { type: 'emote', by: player.id, emoteId, nonce: randomNonce() };
  if (network.role === 'host') relayEmote(message);
  else if (network.role === 'client') network.send(message);
  addFeed(`EMOTE: ${emoteId.toUpperCase()}`, 'gold');
}

/** Host: validate against the live lobby, play on this screen, forward to guests. */
function relayEmote(message: EmoteMessage): void {
  if (network.role !== 'host') return;
  if (message.by !== player.id && !hostLobbyMembers.get(message.by)?.connected) return;
  applyRemoteEmote(message);
  network.send(message);
}

/** Every screen: the sender's rig is a remote everywhere but their own machine. */
function applyRemoteEmote(message: EmoteMessage): void {
  const remote = remotes.get(message.by);
  if (remote) emoteRiggedOperator(remote.root, message.emoteId);
}

/** HF-382: the replicated idle stance for a peer's third-person rig. Falls back
 * to the catalog default for anything absent or off-catalog, mirroring skinId. */
function memberOperatorStanceId(id: string): string {
  const member = privateLobbySnapshot?.members.find((entry) => entry.id === id)
    ?? (network.role === 'host' ? hostLobbyMembers.get(id) : undefined);
  const stance = member && 'stanceId' in member ? member.stanceId : undefined;
  return isOperatorStanceId(stance) ? stance : DEFAULT_OPERATOR_STANCE;
}

/** Write every remote rig's replicated stance onto the root updateRiggedOperator
 * reads. Idempotent and cheap; called whenever the lobby membership changes. */
function syncRemoteOperatorStances(): void {
  for (const [id, remote] of remotes) {
    remote.root.userData.operatorStanceId = memberOperatorStanceId(id);
  }
}

function memberOperatorSkinId(id: string): string {
  const member = privateLobbySnapshot?.members.find((entry) => entry.id === id)
    ?? hostLobbyMembers.get(id);
  const skinId = member?.skinId ?? (id === player.id ? localOperatorSkinId : undefined);
  return skinId !== undefined && isSelectableOperatorSkinId(skinId) ? skinId : 'default';
}

function applyHostLobbyConfig(config: PrivateMatchConfig): void {
  if (network.role !== 'host' || (privateLobbySnapshot?.phase ?? 'waiting') !== 'waiting') return;
  if (hostLobbyMembers.size > config.capacity) {
    setStatus(`Room already has ${hostLobbyMembers.size} players; capacity cannot be ${config.capacity}.`, 'warn');
    renderPrivateLobby();
    return;
  }
  const arenaChanged = privateMatchConfig.arenaId !== config.arenaId;
  privateMatchConfig = config;
  privateMatchMode = config.mode;
  network.setCapacity(config.capacity);
  // HF-328: entering TDM prescribes teams deterministically and stamps the canonical
  // AQUA/CORAL identities, rather than leaving it to the autoBalance toggle.
  const nextMembers = config.mode !== 'ffa'
    ? prescribeTeams([...hostLobbyMembers.values()])
    : [...hostLobbyMembers.values()];
  for (const member of nextMembers) hostLobbyMembers.set(member.id, { ...member, ready: false });
  broadcastHostLobby('waiting');
  if (arenaChanged) {
    lobbyArenaSyncPromise = lobbyArenaSyncPromise
      .catch(() => undefined)
      .then(() => synchronizeLobbyArena());
  }
}

function scheduleDisconnectedLobbyExpiry(playerId: string, delayMs = REJOIN_GRACE_MS): void {
  const reservationMatchEpoch = killstreakMatchEpoch;
  window.setTimeout(() => {
    const disconnectedAt = hostDisconnectedAt.get(playerId);
    const current = hostLobbyMembers.get(playerId);
    if (disconnectedAt === undefined || !current || current.connected
      || !rejoinReservationExpired(disconnectedAt, performance.now())) return;
    hostDisconnectedAt.delete(playerId);
    hostLobbyMembers.delete(playerId);
    hostLobbyTokens.delete(playerId);
    hostLobbyTokenDigests.delete(playerId);
    pendingHostRecoveryJoins.delete(playerId);
    hostLobbyAdmissionInFlight.delete(playerId);
    pendingGuestAuthorityRepairs.delete(playerId);
    hostKillstreakLoadoutAcks.clearActor(playerId);
    const retained = retainedRemoteAuthorities.get(playerId);
    if (retained) {
      const dropPoint = new THREE.Vector3(
        retained.snapshot.x,
        retained.snapshot.y,
        retained.snapshot.z,
      ).add(new THREE.Vector3(0, 0.3, 0));
      dropHeldRailgun(playerId, dropPoint);
      dropHeldTimedMapWeapons(playerId, dropPoint);
    }
    network.forgetPlayerRejoinCredential(playerId);
    hostLobbyConnectionEpochs.delete(playerId);
    authoritativeShotAdmissions.delete(playerId);
    authoritativeScores.delete(playerId);
    forgetTextChatParticipant(playerId);
    remoteSupportAuthorities.delete(playerId);
    remoteGrenadeAuthorities.delete(playerId);
    remoteCombatInventories.delete(playerId);
    remoteCombatInventoryRevisions.delete(playerId);
    remoteHealthAuthorities.delete(playerId);
    retainedRemoteAuthorities.delete(playerId);
    remoteFlashVictimLifeIds.delete(playerId);
    lastAuthoredFlashResults.delete(playerId);
    if (network.role === 'host' && killstreakMatchEpoch === reservationMatchEpoch
      && killstreakRegisteredActors.has(playerId)) {
      killstreakRuntime.unregisterActor(playerId);
      killstreakRegisteredActors.delete(playerId);
      refreshLocalKillstreakSnapshot();
      broadcastKillstreakState();
    }
    broadcastHostLobby(privateLobbySnapshot?.phase ?? 'waiting');
    persistActiveHostMatchCheckpoint();
  }, Math.max(0, delayMs) + 50);
}

function markLobbyDisconnected(playerId: string): void {
  const member = hostLobbyMembers.get(playerId);
  if (!member || playerId === player.id) return;
  if (!member.connected && hostDisconnectedAt.has(playerId)) return;
  hostLobbyMembers.set(playerId, { ...member, connected: false, ready: false, pingMs: null });
  pendingGuestAuthorityRepairs.delete(playerId);
  hostDisconnectedAt.set(playerId, performance.now());
  broadcastHostLobby(privateLobbySnapshot?.phase ?? 'waiting');
  scheduleDisconnectedLobbyExpiry(playerId);
}

function currentHostTimeMs(): number {
  const now = performance.now();
  if (network.role !== 'client') return now;
  hostTimeMapping = monotonicMappedHostNow(hostTimeMapping, now);
  return hostTimeMapping.lastHostTimeMs;
}

function createStateMessage(playerSnapshot = snapshot()): StateMessage {
  return {
    type: 'state',
    player: playerSnapshot,
    hostTimeMs: currentHostTimeMs(),
    continuity: localContinuity,
    rateHz: localSnapshotRateState.rateHz,
    combatInventory: localGuestCombatInventoryProjection(playerSnapshot.seq),
  };
}

function scheduleClockPing(delay = CLOCK_PING_INTERVAL_MS): void {
  if (lobbyClockTimer) clearTimeout(lobbyClockTimer);
  if (network.role !== 'client') return;
  lobbyClockTimer = setTimeout(() => {
    if (network.role !== 'client') return;
    const mappingReady = hostTimeMapping.sampleCount > 0;
    network.send({
      type: 'clock-ping', by: player.id, guestSentMonoMs: performance.now(),
      reportedOffsetMs: mappingReady ? hostTimeMapping.offsetMs : null,
      reportedRttMs: mappingReady ? hostTimeMapping.rttMs : null,
      reportedJitterMs: mappingReady ? hostTimeMapping.jitterMs : null,
      reportedUncertaintyMs: mappingReady ? hostTimeMapping.uncertaintyMs : null,
      nonce: randomNonce(),
    });
    scheduleClockPing();
  }, delay);
}

function acceptClockPong(message: Extract<GameMessage, { type: 'clock-pong' }>): void {
  if (network.role !== 'client' || message.forPlayerId !== player.id || message.by !== privateLobbySnapshot?.hostId) return;
  const observation = observeHostClock(hostTimeMapping, {
    guestSentMonoMs: message.guestSentMonoMs,
    hostReceivedMonoMs: message.hostReceivedMonoMs,
    hostSentMonoMs: message.hostSentMonoMs,
    guestReceivedMonoMs: performance.now(),
  });
  hostTimeMapping = observation.mapping;
  if (!observation.accepted) return;
  localLobbyPingMs = Math.round(hostTimeMapping.rttMs);
  renderPrivateLobby();
}

function sendAuthoritativeScores(targetPlayerId?: string): void {
  if (network.role !== 'host') return;
  const scores = [...authoritativeScores.values()].slice(0, privateMatchConfig.capacity + privateMatchConfig.hostedBotCount);
  const message: MatchScoreMessage = { type: 'match-score', by: player.id, scores, nonce: randomNonce() };
  if (targetPlayerId) network.sendToPlayer(targetPlayerId, message);
  else network.send(message);
}

function publishRangeScore(): void {
  if (selectedArena.id !== 'gun-range' || network.role === 'offline') return;
  const claim: RangeScoreClaimMessage = {
    type: 'range-score-claim', by: player.id, score: rangeScore, hits: targetHits, shots: rangeShotsFired, nonce: randomNonce(),
  };
  if (network.role === 'host') {
    const current = authoritativeScores.get(player.id) ?? emptyPlayerScore(player.id);
    authoritativeScores.set(player.id, { ...current, rangeScore, rangeHits: targetHits, rangeShots: rangeShotsFired });
    sendAuthoritativeScores();
  } else {
    network.send(claim);
  }
}

function acceptRangeScoreClaim(message: RangeScoreClaimMessage): void {
  if (network.role !== 'host' || selectedArena.id !== 'gun-range' || !hostLobbyMembers.has(message.by)) return;
  const current = authoritativeScores.get(message.by) ?? emptyPlayerScore(message.by);
  if (message.score < (current.rangeScore ?? 0) || message.hits < (current.rangeHits ?? 0) || message.shots < (current.rangeShots ?? 0)) return;
  authoritativeScores.set(message.by, { ...current, rangeScore: message.score, rangeHits: message.hits, rangeShots: message.shots });
  sendAuthoritativeScores();
}

function presentLocalDamageDelta(previous: PlayerScore | undefined, next: PlayerScore | undefined): void {
  if (!next) return;
  const dealt = next.damageDealt - (previous?.damageDealt ?? 0);
  const taken = next.damageTaken - (previous?.damageTaken ?? 0);
  if (dealt > 0) addFeed(`DAMAGE DEALT +${dealt} · ${next.damageDealt} TOTAL`, 'gold', { damageDealt: dealt });
  if (taken > 0) addFeed(`DAMAGE TAKEN +${taken} · ${next.damageTaken} TOTAL`, 'coral', { damageTaken: taken });
}

function recordAuthoritativeDamage(attackerId: string, victimId: string, damage: number): void {
  if (network.role !== 'host' || damage <= 0) return;
  if (killstreakRuntime.recordActorDamage(victimId)) broadcastKillstreakState();
  if (attackerId === victimId) return;
  const previousLocal = authoritativeScores.get(player.id);
  const next = recordAuthoritativeDamageScores(authoritativeScores, attackerId, victimId, damage);
  authoritativeScores.clear();
  for (const [id, score] of next) authoritativeScores.set(id, score);
  presentLocalDamageDelta(previousLocal, authoritativeScores.get(player.id));
  sendAuthoritativeScores();
}

function acceptAuthoritativeScores(message: MatchScoreMessage): void {
  if (network.role !== 'client' || message.by !== privateLobbySnapshot?.hostId) return;
  const previousLocal = authoritativeScores.get(player.id);
  authoritativeScores.clear();
  for (const score of message.scores) {
    authoritativeScores.set(score.id, score);
    if (score.id === player.id) {
      player.kills = score.kills;
      player.deaths = score.deaths;
    }
    const remote = remotes.get(score.id);
    if (remote) remote.snapshot = { ...remote.snapshot, kills: score.kills, deaths: score.deaths };
  }
  if (privateLobbySnapshot) privateLobbySnapshot = { ...privateLobbySnapshot, scores: message.scores };
  presentLocalDamageDelta(previousLocal, authoritativeScores.get(player.id));
}

async function synchronizeLobbyArena(admissionToken?: MatchAdmissionToken): Promise<void> {
  const arenaId = privateLobbySnapshot?.config.arenaId ?? privateMatchConfig.arenaId;
  if (selectedArena.id !== arenaId) {
    // An active-match rejoin already owns a match-admission token, so its
    // arena rebuild must be allowed through the generic "preparing" guard.
    // The token remains the fail-closed authority at every awaited boundary.
    await activateArenaSelection(arenaId, admissionToken !== undefined, admissionToken);
  }
}

function matchAdmissionIdentity(
  mode: 'solo' | 'host' | 'client',
  activeAtHostTimeMs: number | null,
  activeAtEpochMs: number | null,
): MatchAdmissionIdentity {
  const snapshot = mode === 'solo' ? null : privateLobbySnapshot;
  return Object.freeze({
    mode,
    role: network.role,
    arenaId: snapshot?.config.arenaId ?? selectedArena.id,
    roomCode: network.roomCode,
    connectionEpoch: localConnectionEpoch,
    lobbyRevision: snapshot?.revision ?? (mode === 'solo' ? null : privateLobbyRevision),
    lobbyPhase: snapshot?.phase ?? null,
    activeAtHostTimeMs,
    activeAtEpochMs,
  });
}

function observedMatchAdmissionIdentity(token: MatchAdmissionToken): MatchAdmissionIdentity {
  const snapshot = token.mode === 'solo' ? null : privateLobbySnapshot;
  return matchAdmissionIdentity(
    token.mode,
    snapshot?.activeAtHostTimeMs ?? (token.mode === 'solo' ? null : privateMatchActiveAtHostTimeMs),
    snapshot?.activeAtEpochMs ?? (token.mode === 'solo' ? null : privateMatchActiveAtEpochMs),
  );
}

function lobbyAuthoritySupersedesActiveAdmission(
  authority: Pick<
    MatchAdmissionIdentity,
    'arenaId' | 'lobbyRevision' | 'lobbyPhase' | 'activeAtHostTimeMs' | 'activeAtEpochMs'
  >,
): boolean {
  const token = matchAdmissionCoordinator.token();
  if (!token) return false;
  return !sameMatchAdmissionAuthority(token, Object.freeze({
    mode: token.mode,
    role: network.role,
    roomCode: network.roomCode,
    connectionEpoch: localConnectionEpoch,
    ...authority,
  }));
}

function assertMatchAdmissionCurrent(token: MatchAdmissionToken): void {
  matchAdmissionCoordinator.assertCurrent(token, observedMatchAdmissionIdentity(token));
}

async function awaitMatchAdmission<T>(token: MatchAdmissionToken, pending: Promise<T>): Promise<T> {
  const value = await pending;
  assertMatchAdmissionCurrent(token);
  return value;
}

function invalidateMatchAdmission(reason: string): void {
  matchAdmissionCoordinator.invalidate(reason);
  if (!matchAdmissionCoordinator.token()) matchStartPreparing = false;
  syncArenaSelectionUi();
}

function settleMatchAdmissionRun(token: MatchAdmissionToken): void {
  if (activeMatchAdmissionRun?.token === token) activeMatchAdmissionRun = null;
  if (!matchAdmissionCoordinator.token()) matchStartPreparing = false;
  syncArenaSelectionUi();
}

// Automatic solo redeploy budget for intermittent renderer pipeline failures. Restored
// to 2 by every explicit Solo click; spent only on WebGPU/pipeline-class errors.
let soloRendererAutoRetriesRemaining = 4;

function handleMatchAdmissionFailure(
  token: MatchAdmissionToken,
  mode: 'solo' | 'host' | 'client',
  errorValue: unknown,
): MatchAdmissionResult {
  const error = errorValue instanceof Error ? errorValue : new Error(String(errorValue));
  if (isMatchAdmissionSuperseded(error) || !matchAdmissionCoordinator.owns(token)) {
    return matchAdmissionResult(token, 'superseded', error);
  }
  gameStarted = false;
  if (mode === 'host') {
    // The countdown/start pair was already published. This owned failure must
    // author a strictly newer waiting snapshot before releasing the token so
    // every guest cancels the same clocks instead of entering a split match.
    assertMatchAdmissionCurrent(token);
    returnPrivateMatchToLobby(true, token);
    setStatus(`Deployment cancelled for everyone: ${error.message}. Ready up and retry.`, 'error');
  } else if (mode === 'solo') {
    // A cold arena/renderer failure is recoverable. The exact failed arena
    // generation is evicted by performArenaSelection; return to deployment so
    // the next explicit Solo click constructs a fresh generation.
    resetForMode(true);
    killstreakLoadoutController.releaseAfterMatch();
    killstreakMenuBinding.setMatchActive(false);
    matchWebGpuQualityFrozen = false;
    weaponView.setPresentationVisible(false);
    hudRoot.hidden = true;
    applyMenuLifecycle({ type: 'return-pre-match' });
    setArenaMenuCamera();
    matchAdmissionCoordinator.complete(token);
    matchStartPreparing = false;
    // Chrome 153's Tint can fail pipeline creation INTERMITTENTLY in default Chrome
    // ("swizzle view instruction still has usages after lowering" - measured live,
    // 2026-08-28; the same deploy retried clean). This branch already documents the
    // failed generation as evicted and a fresh Solo click as the recovery, so perform
    // that click for the player - at most twice per explicit attempt, and only for
    // renderer-class errors. Everything else keeps the honest failure message.
    const rendererClassFailure = /webgpu|pipeline|commandbuffer|queue completion|device lost|tint/i.test(error.message);
    if (soloRendererAutoRetriesRemaining > 0 && rendererClassFailure) {
      soloRendererAutoRetriesRemaining -= 1;
      // 2026-08-29 measurement: the Tint race is TIMING-sensitive - cold
      // network streaming fails 3/3, warm-cache/local timing 0/4. Later
      // attempts run on warm caches, so four tries multiply escape odds.
      // REPAIR BEFORE RETRY: the debounced console-error repair cannot fire
      // inside the admission window, so an errored pipeline would survive in
      // three's cache and poison every retry with the same silent skip-draw.
      // Purge synchronously here; the retry then re-creates those pipelines
      // with fresh timing instead of reusing the corpse.
      const attempt = 4 - soloRendererAutoRetriesRemaining;
      setStatus(`Renderer hiccup while preparing deployment - rebuilding and retrying (attempt ${attempt} of 4)...`, 'warn');
      window.setTimeout(() => {
        void (async () => {
          if (matchStartPreparing || gameStarted) return;
          if (renderRuntime.backend === 'webgpu') {
            // Purge the errored pipeline cache entries, then RE-CREATE every
            // missing pipeline through compileAsync: measured 2026-08-29, the
            // async path is clean 5/5 on the affected Chrome 153 build while
            // sync creation races Tint. After this pass the retry's renders
            // find warm pipelines and never touch createRenderPipeline.
            const swept = sweepErroredPipelines(
              renderRuntime.renderer as Parameters<typeof sweepErroredPipelines>[0],
              scene,
            );
            try {
              // A device that just errored can leave compileAsync pending
              // forever; the recovery must never strand the player on the
              // deployment screen, so the pass is time-boxed and advisory.
              await Promise.race([
                renderRuntime.compile(scene, camera, scene),
                new Promise((resolve) => { window.setTimeout(resolve, 8_000); }),
              ]);
            } catch { /* the retry itself remains the arbiter */ }
            const counters = {
              sweeps: Number(sessionStorage.getItem('atomic-acres:tint-admission-sweeps') ?? '0') + 1,
              purged: swept.purged,
            };
            try {
              sessionStorage.setItem('atomic-acres:tint-admission-sweeps', String(counters.sweeps));
              sessionStorage.setItem('atomic-acres:tint-admission-last-purge', String(counters.purged));
            } catch { /* storage-less contexts lose only diagnostics */ }
            document.documentElement.dataset.tintAdmissionSweeps = String(counters.sweeps);
            document.documentElement.dataset.tintAdmissionLastPurge = String(counters.purged);
          }
          network.close();
          resetForMode();
          resetPrivateLobbyState();
          void startGame('solo');
        })();
      }, 1_500);
    } else if (rendererClassFailure) {
      // Owner 2026-08-30: no WebGL2 fallback. Four repaired-and-retried
      // WebGPU attempts failing the same way is an environment problem the
      // player must hear about honestly, on the menu, with their retries
      // reset for another manual attempt.
      soloRendererAutoRetriesRemaining = 4;
      setStatus(
        'The graphics driver kept refusing this deployment. Close other GPU-heavy apps or restart the browser, then deploy again.',
        'error',
      );
    } else {
      setStatus(`Deployment preparation failed: ${error.message}. Retry to build fresh assets.`, 'warn');
    }
  } else {
    clientWorldRepairAdmission = null;
    pendingClientReconnectWorldRepairConnectionEpoch = null;
    clearBots();
    killstreakLoadoutController.releaseAfterMatch();
    killstreakMenuBinding.setMatchActive(false);
    matchWebGpuQualityFrozen = false;
    matchAdmissionCoordinator.complete(token);
    matchStartPreparing = false;
    showFatalError(error);
  }
  return matchAdmissionResult(token, 'failed', error);
}

async function runPrivateMatchAdmission(
  token: MatchAdmissionToken,
  mode: 'host' | 'client',
  activeAtHostTimeMs: number,
  activeAtEpochMs: number,
  observedHostTimeMs: number,
  hostRecovery: HostMatchCheckpoint | undefined,
  predecessor: Promise<MatchAdmissionResult> | null,
): Promise<MatchAdmissionResult> {
  try {
    if (predecessor) {
      await predecessor;
      assertMatchAdmissionCurrent(token);
      // A superseded attempt may have populated match-only pools before its
      // awaited boundary returned. Clean those remnants only after it has
      // settled and while this successor owns the coordinator.
      resetForMode(true);
      assertMatchAdmissionCurrent(token);
    }
    await awaitMatchAdmission(token, lobbyArenaSyncPromise);
    await awaitMatchAdmission(token, synchronizeLobbyArena(token));
    if (gameStarted) return matchAdmissionResult(token, 'superseded', 'A match is already active');
    const arenaId = privateLobbySnapshot?.config.arenaId ?? privateMatchConfig.arenaId;
    if (selectedArena.id !== arenaId) {
      throw new Error(`Could not synchronize ${arenaSelection(arenaId).displayName}`);
    }
    assertMatchAdmissionCurrent(token);
    privateMatchActiveAtHostTimeMs = activeAtHostTimeMs;
    privateMatchActiveAtEpochMs = activeAtEpochMs;
    privateMatchMode = privateLobbySnapshot?.config.mode ?? privateMatchConfig.mode;
    const observedGuestMonoMs = performance.now();
    const activeAtLocalMonoMs = mode === 'host'
      ? activeAtHostTimeMs
      : hostTimeToGuestMono(hostTimeMapping, activeAtHostTimeMs, observedGuestMonoMs, observedHostTimeMs);
    return await startGame(mode, false, activeAtLocalMonoMs, hostRecovery, token);
  } catch (error) {
    return handleMatchAdmissionFailure(token, mode, error);
  }
}

function beginPrivateMatch(
  mode: 'host' | 'client',
  activeAtHostTimeMs: number,
  activeAtEpochMs: number,
  observedHostTimeMs: number,
  hostRecovery?: HostMatchCheckpoint,
): Promise<MatchAdmissionResult> {
  if (gameStarted) {
    return Promise.resolve(Object.freeze({
      status: 'superseded',
      generation: matchAdmissionGeneration,
      reason: 'A match is already active',
    }));
  }
  const begin = matchAdmissionCoordinator.begin(matchAdmissionIdentity(
    mode,
    activeAtHostTimeMs,
    activeAtEpochMs,
  ));
  if (!begin.started) {
    return activeMatchAdmissionRun?.token === begin.token
      ? activeMatchAdmissionRun.promise
      : Promise.resolve(matchAdmissionResult(begin.token, 'superseded', 'The same admission is already pending'));
  }
  matchAdmissionGeneration = begin.token.generation;
  matchStartPreparing = true;
  syncArenaSelectionUi();
  const predecessor = activeMatchAdmissionRun?.promise ?? null;
  const promise = runPrivateMatchAdmission(
    begin.token,
    mode,
    activeAtHostTimeMs,
    activeAtEpochMs,
    observedHostTimeMs,
    hostRecovery,
    predecessor,
  );
  activeMatchAdmissionRun = Object.freeze({ token: begin.token, promise });
  void promise.finally(() => settleMatchAdmissionRun(begin.token));
  return promise;
}

function hostStartPrivateMatch(): void {
  if (network.role !== 'host') return;
  // HF-323: refuse to start while a guest admission is in-flight or transport connection is pending
  const pendingGuest = hostHasPendingGuestConnection();
  if (pendingGuest) {
    setStatus('A player is currently joining the room.', 'warn');
    return;
  }
  const candidate = hostSnapshot('waiting');
  if (!canHostCommitStart(candidate, pendingGuest)) {
    setStatus('Every connected guest must be ready before the host starts.', 'warn');
    return;
  }
  const hostMember = hostLobbyMembers.get(player.id);
  if (!hostMember?.connected) return;
  if (!hostMember.ready) {
    hostLobbyMembers.set(player.id, { ...hostMember, ready: true });
  }
  const current = hostSnapshot('waiting');
  if (!canHostStart(current, pendingGuest)) {
    setStatus('Every connected guest must be ready before the host starts.', 'warn');
    return;
  }
  clearStoredHostMatchCheckpoint();
  privateMatchActiveAtHostTimeMs = performance.now() + LOBBY_START_LEAD_MS;
  privateMatchActiveAtEpochMs = Date.now() + LOBBY_START_LEAD_MS;
  privateLobbyRevision += 1;
  privateLobbySnapshot = hostSnapshot('countdown');
  const admission = beginPrivateMatch(
    'host',
    privateMatchActiveAtHostTimeMs,
    privateMatchActiveAtEpochMs,
    performance.now(),
  );
  const admissionToken = matchAdmissionCoordinator.token();
  if (!admissionToken || admissionToken.mode !== 'host') {
    invalidateMatchAdmission('Could not establish authoritative host admission');
    setStatus('Could not establish authoritative match admission.', 'error');
    return;
  }
  try {
    assertMatchAdmissionCurrent(admissionToken);
    network.send({ type: 'lobby-state', by: player.id, snapshot: privateLobbySnapshot, nonce: randomNonce() });
    assertMatchAdmissionCurrent(admissionToken);
    network.send({
      type: 'lobby-start', by: player.id, activeAtHostTimeMs: privateMatchActiveAtHostTimeMs,
      activeAtEpochMs: privateMatchActiveAtEpochMs, hostSentTimeMs: performance.now(),
      revision: privateLobbyRevision, nonce: randomNonce(),
    });
  } catch (error) {
    handleMatchAdmissionFailure(admissionToken, 'host', error);
  }
  renderPrivateLobby();
  void admission;
}

function returnPrivateMatchToLobby(asHost: boolean, admissionToken?: MatchAdmissionToken): void {
  if (admissionToken && !matchAdmissionCoordinator.owns(admissionToken)) return;
  clientWorldRepairAdmission = null;
  pendingClientReconnectWorldRepairConnectionEpoch = null;
  hostKillstreakLoadoutAcks.clear();
  if (asHost && network.role === 'host') clearStoredHostMatchCheckpoint();
  gameStarted = false;
  matchFinished = false;
  // Both clocks form one lobby-start identity. Leaving either populated makes
  // the waiting snapshot invalid and prevents peers from readying a rematch.
  privateMatchActiveAtHostTimeMs = null;
  privateMatchActiveAtEpochMs = null;
  if (asHost && network.role === 'host') {
    authoritativeScores.clear();
    // Retained remote authority is a MID-MATCH resume mechanism: it preserves
    // a disconnector's life/health for the rejoin grace of the match they left.
    // Returning everyone to the lobby ends that match, so the retained
    // snapshots are now history - but nothing cleared them, so a guest who
    // rejoined the waiting lobby and started the next match was recreated from
    // the PREVIOUS match's snapshot in awaitingReplacementState and froze for
    // everyone, permanently. The next match must begin with no ghosts.
    retainedRemoteAuthorities.clear();
    remoteHealthAuthorities.clear();
    for (const member of hostLobbyMembers.values()) {
      hostLobbyMembers.set(member.id, { ...member, ready: false });
      authoritativeScores.set(member.id, emptyPlayerScore(member.id));
    }
    try {
      broadcastHostLobby('waiting');
    } finally {
      if (admissionToken) matchAdmissionCoordinator.invalidate('Host returned the failed admission to the lobby');
    }
  }
  // The authoritative waiting revision must exist before any potentially
  // fallible local teardown. Once published, invalidate this generation so an
  // awaited continuation cannot commit while the local presentation resets.
  if (admissionToken && matchAdmissionCoordinator.owns(admissionToken)) {
    matchAdmissionCoordinator.invalidate('Host returned the failed admission to the lobby');
  }
  resetForMode(admissionToken !== undefined);
  killstreakLoadoutController.releaseAfterMatch();
  killstreakMenuBinding.setMatchActive(false);
  matchWebGpuQualityFrozen = false;
  weaponView.setPresentationVisible(false);
  hudRoot.hidden = true;
  clearCentreBanner(); // HF-339
  element<HTMLElement>('#countdown').hidden = true;
  applyMenuLifecycle({ type: 'return-pre-match' });
  setArenaMenuCamera();
  if (document.pointerLockElement) void document.exitPointerLock();
  renderPrivateLobby();
  renderTextChat();
  setStatus(asHost ? 'Lobby reset — ready up for another match.' : 'Host returned everyone to the lobby.', 'ok');
}

/** HF-347: adopt the host's training-dummy lifecycle state on a guest. The
 * arena may not be built yet when an early snapshot arrives; unknown ids are
 * skipped and the next heartbeat (every clock ping) self-heals. */
function applyReplicatedGunRangeDummyState(entries: LobbySnapshot['testDummies']): void {
  if (network.role !== 'client' || !entries || selectedArena.id !== 'gun-range') return;
  for (const entry of entries) {
    const dummy = arena.targets.find(
      (target) => target.id === entry.id && target.kind === 'training-dummy',
    );
    if (!dummy) continue;
    dummy.active = entry.active;
    dummy.health = Math.max(0, Math.min(dummy.maxHealth, entry.health));
    dummy.respawnAt = entry.respawnAtHostTimeMs;
    dummy.root.visible = entry.active;
  }
}

function acceptLobbyState(message: LobbyStateMessage): void {
  if (network.role !== 'client' || message.by !== message.snapshot.hostId) return;
  if (privateLobbySnapshot && message.snapshot.revision < privateLobbySnapshot.revision) return;
  if (message.snapshot.matchClock && gunRangeMatchClockState
    && message.snapshot.matchClock.revision < gunRangeMatchClockState.revision) return;
  const previousSnapshot = privateLobbySnapshot;
  const newerRevision = previousSnapshot === null || message.snapshot.revision > previousSnapshot.revision;
  if (newerRevision && previousSnapshot !== null && lobbyAuthoritySupersedesActiveAdmission({
    arenaId: message.snapshot.config.arenaId,
    lobbyRevision: message.snapshot.revision,
    lobbyPhase: message.snapshot.phase,
    activeAtHostTimeMs: message.snapshot.activeAtHostTimeMs,
    activeAtEpochMs: message.snapshot.activeAtEpochMs,
  })) {
    invalidateMatchAdmission(`Lobby advanced to revision ${message.snapshot.revision}`);
  }
  const returningToLobby = message.snapshot.phase === 'waiting'
    && (gameStarted || matchStartPreparing)
    && previousSnapshot?.phase !== 'waiting';
  const endingFromHost = message.snapshot.phase === 'ended' && gameStarted && matchState.phase !== 'ended';
  privateLobbySnapshot = message.snapshot;
  syncRemoteOperatorStances(); // HF-382: stance changes land on live rigs mid-match
  if (message.snapshot.phase === 'waiting') {
    // HF-322: A join into a WAITING lobby must clear awaitingCanonicalGuestAuthority rather than leaving it armed
    awaitingCanonicalGuestAuthority = false;
    awaitingAuthoritativeRejoinContinuity = false;
    pendingGuestResumeAuthority = null;
    pendingClientReconnectWorldRepairConnectionEpoch = null;
    clientReconnectWorldRepairAttempts = 0;
    clearClientWorldRepairTimeout();
  }
  privateMatchConfig = message.snapshot.config;
  privateMatchMode = message.snapshot.config.mode;
  privateMatchActiveAtHostTimeMs = message.snapshot.activeAtHostTimeMs;
  privateMatchActiveAtEpochMs = message.snapshot.activeAtEpochMs;
  gunRangeMatchClockState = message.snapshot.matchClock;
  gunRangeTestBayDoorState = message.snapshot.testBayDoor;
  applyReplicatedGunRangeDummyState(message.snapshot.testDummies);
  // HF-360: prefetch every member's selected skin so third-person spawns never
  // race the lazy asset load.
  for (const member of message.snapshot.members) {
    if (member.skinId !== undefined && isSelectableOperatorSkinId(member.skinId)) {
      void loadOperatorSkinAsset(member.skinId);
    }
  }
  if (!gunRangeMatchClockState) gunRangeMatchClockOccupantIds = Object.freeze([]);
  lobbyArenaSyncPromise = lobbyArenaSyncPromise
    .catch(() => undefined)
    .then(() => synchronizeLobbyArena());
  authoritativeScores.clear();
  for (const score of message.snapshot.scores) authoritativeScores.set(score.id, score);
  const localMember = message.snapshot.members.find((member) => member.id === player.id);
  if (localMember) {
    player.team = localMember.team;
    localLobbyReady = localMember.ready;
    localDhv = localMember.dhv;
    element<HTMLSelectElement>('#team').value = String(localMember.team);
  }
  if (returningToLobby) {
    returnPrivateMatchToLobby(false);
    return;
  }
  if (endingFromHost) endTimedMatchFromAuthority(performance.now());
  else if (gameStarted) projectActiveGunRangeMatchClock(performance.now());
  renderPrivateLobby();
  renderTextChat();
  if (message.snapshot.activeAtHostTimeMs !== null && message.snapshot.activeAtEpochMs !== null
    && message.snapshot.phase !== 'waiting' && !gameStarted) {
    void beginPrivateMatch('client', message.snapshot.activeAtHostTimeMs, message.snapshot.activeAtEpochMs, message.snapshot.snapshotHostTimeMs);
  }
}

function authorizeRedeploy(message: RedeployCommitMessage, now = performance.now()): void {
  authorizedRemoteRedeploys.set(message.target, {
    primary: message.primary,
    secondary: message.secondary,
    grenade: message.grenade,
    expiresAt: now + 5_000,
    nonce: message.nonce,
  });
}

function acceptRedeployCommit(message: RedeployCommitMessage): void {
  if (network.role !== 'client' || message.by !== privateLobbySnapshot?.hostId || processedNonces.has(message.nonce)) return;
  processedNonces.add(message.nonce);
  authorizeRedeploy(message);
  if (message.target === player.id) {
    applyLocalClassRedeploy({ primary: message.primary, secondary: message.secondary, grenade: message.grenade }, true);
    authorizedRemoteRedeploys.delete(player.id);
  }
  trimNonceSet();
}

function handleLobbyMessage(message: GameMessage): boolean {
  // HF-325. These arrive only from the host: all three are
  // isHostAuthorityMessage, so network.ts drops any of them sent by a guest.
  if (message.type === 'host-succession-mandate') {
    if (network.role === 'client' && message.by === privateLobbySnapshot?.hostId) {
      const accept = acceptSuccessionMandate(
        successorHoldings, message, network.roomCode, Date.now(),
      );
      successorHoldings = accept.holdings;
      lastMandateAccept = { accepted: accept.accepted, reason: accept.reason };
    }
    return true;
  }
  if (message.type === 'host-authority-mirror') {
    if (network.role === 'client' && message.by === privateLobbySnapshot?.hostId) {
      const receivedAtEpochMs = Date.now();
      const accept = acceptAuthorityMirror(successorHoldings, message, {
        selfId: player.id,
        roomCode: network.roomCode,
        receivedAtEpochMs,
        // sender - receiver, which is the convention acceptAuthorityMirror
        // documents and negates internally. One-way latency (tens of ms) is
        // the error term; the point is to cancel HOURS of wall-clock skew, not
        // milliseconds. Do NOT reuse hostTimeMapping.offsetMs — that is a
        // performance.now() mapping, not an epoch offset.
        hostClockOffsetMs: message.hostEpochMs - receivedAtEpochMs,
      });
      successorHoldings = accept.holdings;
      lastMirrorAccept = { accepted: accept.accepted, reason: accept.reason };
    }
    return true;
  }
  if (message.type === 'host-promoted') {
    const roster = successionRoster();
    if (network.role === 'client' && roster) {
      const result = acceptHostPromoted(successorHoldings, message, {
        roomCode: network.roomCode,
        roster,
      });
      successorHoldings = result.holdings;
      // On acceptance the transport re-point rides the EXISTING reconnect
      // loop: the promoted host claimed the SAME room-code peer id this
      // client's reconnect attempts already target, so the next attempt lands
      // on the new host and normal rejoin admission takes over. This branch
      // fences the term so a stale host cannot win the follower back.
    }
    if (network.role === 'host') {
      const conflict = observeHostPromotion(hostSuccessionPublisher, message);
      hostSuccessionPublisher = conflict.publisher;
      if (conflict.action === 'stand-down') standDownAsSupersededHost(message.term);
    }
    return true;
  }
  if (message.type === 'chat-submit') {
    admitHostChatSubmit(message);
    return true;
  }
  if (message.type === 'chat-message') {
    acceptHostChatMessage(message);
    return true;
  }
  if (message.type === 'chat-history') {
    acceptHostChatHistory(message);
    return true;
  }
  if (message.type === 'lobby-join') {
    void admitLobbyJoin(message);
    return true;
  }
  if (message.type === 'lobby-ready') {
    updateHostReady(message);
    return true;
  }
  if (message.type === 'lobby-team') {
    updateHostTeam(message);
    return true;
  }
  if (message.type === 'lobby-handicap') {
    updateHostHandicap(message);
    return true;
  }
  if (message.type === 'lobby-squad') {
    updateHostSquad(message);
    return true;
  }
  if (message.type === 'lobby-skin') {
    updateHostSkin(message);
    return true;
  }
  if (message.type === 'lobby-stance') {
    updateHostStance(message);
    return true;
  }
  if (message.type === 'emote') {
    if (network.role === 'host') relayEmote(message);
    else if (message.by !== player.id) applyRemoteEmote(message);
    return true;
  }
  if (message.type === 'redeploy-request') {
    if (network.role === 'host' && gameStarted && matchState.phase === 'active' && !processedNonces.has(message.nonce)) {
      const member = hostLobbyMembers.get(message.by);
      const remote = remotes.get(message.by);
      const health = remoteHealthAuthorities.get(message.by);
      if (member && remote && health?.alive) {
        const now = performance.now();
        const result = applyAuthoritativeRemoteRedeploy(health, now);
        if (result.applied) {
          dropHeldRailgun(message.by, remote.target.clone().add(new THREE.Vector3(0, 0.3, 0)));
          dropHeldTimedMapWeapons(message.by, remote.target.clone().add(new THREE.Vector3(0, 0.3, 0)));
          processedNonces.add(message.nonce);
          remoteHealthAuthorities.set(message.by, result.state);
          clearRemoteReloadAuthority(message.by);
          const canonicalSnapshot: PlayerSnapshot = Object.freeze({
            ...remote.snapshot,
            hp: result.state.hp,
            primary: message.primary,
            secondary: message.secondary,
            grenade: message.grenade,
            weapon: message.primary,
          });
          remote.snapshot = canonicalSnapshot;
          const grenadeAuthority = recordRemoteGrenadeRespawn(
            remoteGrenadeAuthorities.get(message.by) ?? createRemoteGrenadeAuthorityState(message.grenade),
            message.grenade,
            now,
          );
          remoteGrenadeAuthorities.set(message.by, grenadeAuthority);
          resetRemoteCombatInventory(canonicalSnapshot, grenadeAuthority.remaining);
          remoteSupportAuthorities.set(message.by, recordRemoteSupportDeath(
            remoteSupportAuthorities.get(message.by) ?? createRemoteSupportAuthorityState(),
          ));
          hostTriggerAuthorities.reset(message.by, 'respawn');
          retainedRemoteAuthorities.set(message.by, Object.freeze({
            snapshot: Object.freeze({ ...canonicalSnapshot }),
            continuity: remote.continuity,
          }));
          const commit: RedeployCommitMessage = {
            type: 'redeploy-commit', protocolVersion: MULTIPLAYER_PROTOCOL_VERSION,
            by: player.id, target: message.by, primary: message.primary,
            secondary: message.secondary, grenade: message.grenade,
            hostTimeMs: now, nonce: randomNonce(),
          };
          authorizeRedeploy(commit, now);
          persistActiveHostMatchCheckpoint();
          network.send(commit);
          recordMatchDiagnostic('field-kit-redeploy', 'accepted', {
            actorId: message.by,
            reason: 'host-authoritative-noncombat-redeploy',
            modifiers: [`primary:${message.primary}`, `secondary:${message.secondary}`, `grenade:${message.grenade}`],
          });
          trimNonceSet();
        }
      }
    }
    return true;
  }
  if (message.type === 'redeploy-commit') {
    acceptRedeployCommit(message);
    return true;
  }
  if (message.type === 'lobby-state') {
    acceptLobbyState(message);
    return true;
  }
  if (message.type === 'lobby-start') {
    if (network.role === 'client' && message.by === privateLobbySnapshot?.hostId && message.revision >= (privateLobbySnapshot?.revision ?? 0)) {
      if (message.revision > (privateLobbySnapshot?.revision ?? 0) && lobbyAuthoritySupersedesActiveAdmission({
        arenaId: privateLobbySnapshot?.config.arenaId ?? selectedArena.id,
        lobbyRevision: message.revision,
        lobbyPhase: 'countdown',
        activeAtHostTimeMs: message.activeAtHostTimeMs,
        activeAtEpochMs: message.activeAtEpochMs,
      })) {
        invalidateMatchAdmission(`Lobby start advanced to revision ${message.revision}`);
      }
      privateMatchActiveAtHostTimeMs = message.activeAtHostTimeMs;
      privateMatchActiveAtEpochMs = message.activeAtEpochMs;
      if (privateLobbySnapshot) privateLobbySnapshot = {
        ...privateLobbySnapshot,
        revision: message.revision,
        phase: 'countdown',
        snapshotHostTimeMs: message.hostSentTimeMs,
        activeAtHostTimeMs: message.activeAtHostTimeMs,
        activeAtEpochMs: message.activeAtEpochMs,
      };
      if (!gameStarted) void beginPrivateMatch('client', message.activeAtHostTimeMs, message.activeAtEpochMs, message.hostSentTimeMs);
    }
    return true;
  }
  if (message.type === 'lobby-reject') {
    const labels = {
      'room-full': 'Room is full.',
      'identity-in-use': 'That player identity is already connected.',
      'rejoin-denied': 'Rejoin token rejected; open a fresh invite.',
      'match-active': 'Match already active; only reconnecting players may enter.',
      'invalid-config': 'Host settings were rejected.',
      'protocol-mismatch': 'This lobby uses a newer multiplayer protocol. Reload the game and rejoin.',
      'build-mismatch': 'Your build differs from the host\u2019s channel. Open the chooser and join the host\u2019s pass, then rejoin.',
    } as const;
    setStatus(labels[message.reason], 'error');
    invalidateMatchAdmission(`Lobby rejected the active connection: ${message.reason}`);
    clientWorldRepairAdmission = null;
    pendingClientReconnectWorldRepairConnectionEpoch = null;
    network.close();
    privateLobbySnapshot = null;
    renderPrivateLobby();
    resetTextChat();
    syncArenaSelectionUi();
    return true;
  }
  if (message.type === 'clock-ping') {
    if (network.role === 'host') {
      const member = hostLobbyMembers.get(message.by);
      const hostReceivedMonoMs = performance.now();
      const reportedRttMs = message.reportedRttMs ?? peerTimingStates.get(message.by)?.rttMs ?? 0;
      const priorTiming = peerTimingStates.get(message.by) ?? createPeerTimingState();
      if (message.reportedOffsetMs !== null) peerTimingStates.set(message.by, updatePeerTiming(priorTiming, {
        clockOffsetMs: message.reportedOffsetMs,
        rttMs: reportedRttMs,
        jitterMs: message.reportedJitterMs ?? undefined,
        uncertaintyMs: message.reportedUncertaintyMs ?? undefined,
      }));
      if (member && message.reportedRttMs !== null) hostLobbyMembers.set(message.by, { ...member, pingMs: Math.round(message.reportedRttMs) });
      const hostSentMonoMs = performance.now();
      network.sendToPlayer(message.by, {
        type: 'clock-pong', by: player.id, forPlayerId: message.by,
        guestSentMonoMs: message.guestSentMonoMs, hostReceivedMonoMs, hostSentMonoMs, nonce: randomNonce(),
      });
      if (member && message.reportedRttMs !== null) broadcastHostLobby(privateLobbySnapshot?.phase ?? 'waiting');
    }
    return true;
  }
  if (message.type === 'clock-pong') {
    acceptClockPong(message);
    return true;
  }
  if (message.type === 'match-score') {
    acceptAuthoritativeScores(message);
    return true;
  }
  if (message.type === 'range-score-claim') {
    acceptRangeScoreClaim(message);
    return true;
  }
  if (message.type === 'lobby-config' || message.type === 'lobby-balance') return true;
  if (message.type === 'leave' && privateLobbySnapshot) {
    removeRemote(message.playerId, message.voluntary ? 'left the lobby' : 'disconnected', !message.voluntary);
    if (network.role === 'host') {
      if (message.voluntary) {
        hostLobbyMembers.delete(message.playerId);
        hostLobbyTokens.delete(message.playerId);
        network.forgetPlayerRejoinCredential(message.playerId);
        hostLobbyConnectionEpochs.delete(message.playerId);
        pendingGuestAuthorityRepairs.delete(message.playerId);
        authoritativeShotAdmissions.delete(message.playerId);
        hostDisconnectedAt.delete(message.playerId);
        authoritativeScores.delete(message.playerId);
        forgetTextChatParticipant(message.playerId);
        broadcastHostLobby(privateLobbySnapshot.phase);
      } else {
        markLobbyDisconnected(message.playerId);
      }
    }
    return true;
  }
  return false;
}

/** One self-cancelling per-tick refresh while the hosted countdown phase is
 * live, so the DEPLOYING IN 5..1 title counts down without a standing interval.
 * renderPrivateLobby stops rescheduling the moment the phase leaves countdown. */
let lobbyCountdownRefreshScheduled = false;
function scheduleLobbyCountdownRefresh(): void {
  if (lobbyCountdownRefreshScheduled || privateLobbySnapshot?.phase !== 'countdown') return;
  lobbyCountdownRefreshScheduled = true;
  window.setTimeout(() => {
    lobbyCountdownRefreshScheduled = false;
    renderPrivateLobby();
  }, 250);
}

function renderPrivateLobby(): void {
  const section = element<HTMLElement>('#private-lobby');
  const lobbyAvailable = network.role !== 'offline' || privateLobbySnapshot !== null;
  const lobbyVisible = !gameStarted && lobbyAvailable;
  menu.classList.toggle('private-lobby-active', lobbyVisible);
  syncArenaSelectionUi();
  if (!lobbyAvailable) {
    section.hidden = true;
    return;
  }
  section.hidden = !lobbyVisible;
  element<HTMLButtonElement>('#solo').disabled = true;
  element<HTMLButtonElement>('#host').disabled = true;
  element<HTMLButtonElement>('#join').disabled = true;
  const snapshot = privateLobbySnapshot;
  const members = snapshot?.members ?? (network.role === 'host' ? [...hostLobbyMembers.values()] : []);
  const connectedCount = members.filter((member) => member.connected).length;
  const capacity = snapshot?.config.capacity ?? privateMatchConfig.capacity;
  element<HTMLElement>('#lobby-capacity-label').textContent = `${connectedCount} / ${capacity}`;
  // The hosted 5-4-3-2-1: the phase carries the host's shared epoch, so every
  // client counts the same five seconds from one authoritative instant. Re-render
  // on a short local tick while the phase lasts; it stops itself otherwise.
  const countdownRemainS = snapshot?.phase === 'countdown' && snapshot.activeAtEpochMs !== null
    ? Math.max(1, Math.min(5, Math.ceil((snapshot.activeAtEpochMs - Date.now()) / 1000)))
    : null;
  element<HTMLElement>('#private-lobby-title').textContent = snapshot?.phase === 'active'
    ? 'MATCH IN PROGRESS'
    : countdownRemainS !== null ? `DEPLOYING IN ${countdownRemainS}` : 'WAITING ROOM';
  if (countdownRemainS !== null) scheduleLobbyCountdownRefresh();
  const hostControls = network.role === 'host' && (snapshot?.phase ?? 'waiting') === 'waiting';
  const arenaInput = element<HTMLSelectElement>('#lobby-arena');
  arenaInput.value = snapshot?.config.arenaId ?? privateMatchConfig.arenaId;
  arenaInput.disabled = !hostControls;
  const modeInput = element<HTMLSelectElement>('#lobby-mode');
  const capacityInput = element<HTMLSelectElement>('#lobby-capacity');
  const botInput = element<HTMLSelectElement>('#lobby-bots');
  const balanceInput = element<HTMLInputElement>('#lobby-auto-balance');
  const dominationOption = modeInput.querySelector<HTMLOptionElement>('option[value="domination"]');
  if (dominationOption) {
    const lobbyArena = snapshot?.config.arenaId ?? privateMatchConfig.arenaId;
    dominationOption.disabled = lobbyArena !== 'test2';
    dominationOption.textContent = lobbyArena === 'test2' ? 'DOMINATION' : 'DOMINATION (TEST2)';
  }
  modeInput.value = snapshot?.config.mode ?? privateMatchConfig.mode;
  capacityInput.value = String(capacity);
  botInput.value = String(snapshot?.config.hostedBotCount ?? privateMatchConfig.hostedBotCount);
  balanceInput.checked = snapshot?.config.autoBalance ?? privateMatchConfig.autoBalance;
  const rangeLobby = (snapshot?.config.arenaId ?? privateMatchConfig.arenaId) === 'gun-range';
  modeInput.disabled = !hostControls || rangeLobby;
  capacityInput.disabled = !hostControls;
  botInput.disabled = !hostControls || rangeLobby;
  balanceInput.disabled = !hostControls || modeInput.value === 'ffa' || rangeLobby;
  element<HTMLButtonElement>('#lobby-balance').disabled = !hostControls || modeInput.value === 'ffa' || rangeLobby;
  // HF-377: both limit controls mirror the replicated match contract, so guests
  // read the host's chosen limits before ready-up and cannot edit them.
  const timeLimitInput = element<HTMLSelectElement>('#lobby-time-limit');
  const killLimitInput = element<HTMLSelectElement>('#lobby-kill-limit');
  timeLimitInput.value = String(snapshot?.config.durationMs ?? privateMatchConfig.durationMs);
  killLimitInput.value = (snapshot?.config.scoreLimit ?? privateMatchConfig.scoreLimit) === null ? '' : String(snapshot?.config.scoreLimit ?? privateMatchConfig.scoreLimit);
  timeLimitInput.disabled = !hostControls || rangeLobby;
  killLimitInput.disabled = !hostControls || rangeLobby;
  // LIGHTING: the same mirror for the host's TIME OF DAY choice. A guest reads
  // it and cannot edit it, exactly like the two limits above, because two peers
  // on different hours are arguing about a different match.
  const timeOfDayInput = element<HTMLSelectElement>('#lobby-time-of-day');
  timeOfDayInput.value = (snapshot?.config.timeOfDay ?? privateMatchConfig.timeOfDay) ?? DEFAULT_LIGHTING_TIME_CHOICE;
  // Gun Range is indoors and Map 3 is preview-pinned: both resolve to the
  // authored hour whatever is chosen, so the control is disabled rather than
  // offering a choice that provably does nothing.
  timeOfDayInput.disabled = !hostControls || arenaDaylightProfile(arenaSelection(
    (snapshot?.config.arenaId ?? privateMatchConfig.arenaId),
  ).id).pinned;
  const localMember = members.find((member) => member.id === player.id);
  // HF-328: squad identity is prescribed, so the free name input and colour picker
  // no longer exist in the lobby markup. Project the canonical identity into the
  // read-only label instead.
  const squadLabel = element<HTMLElement>('#lobby-squad-label');
  const localSquad = sanitizeSquadPresentation(
    localMember?.squadName ?? localSquadName,
    localMember?.squadColor ?? localSquadColor,
    localMember?.team ?? player.team,
  );
  squadLabel.textContent = localSquad.name;
  squadLabel.style.setProperty('--lobby-squad-color', localSquad.color);
  // HF-328: with identity prescribed there is no input change event to replicate on,
  // so replicate when the assigned identity actually changes - and only then, so the
  // lobby refresh does not spam the event lane every tick.
  const squadKey = `${localSquad.name}:${localSquad.color}`;
  if (squadKey !== lastCommittedSquadKey) {
    lastCommittedSquadKey = squadKey;
    localSquadName = localSquad.name;
    localSquadColor = localSquad.color;
    commitLocalSquadPresentation();
  }
  // HF-328: a prescribed identity has nothing to disable; dim it when disconnected
  // so the lobby still reads the member's connection state.
  squadLabel.dataset.connected = localMember?.connected ? 'true' : 'false';
  const lobbyArenaSynchronized = !snapshot
    || arenaSelectionReady && selectedArena.id === snapshot.config.arenaId;
  trackLobbyArenaSyncDeadline(lobbyArenaSynchronized, snapshot?.config.arenaId ?? null);
  localLobbyReady = localMember?.ready ?? localLobbyReady;
  const ready = element<HTMLButtonElement>('#lobby-ready');
  ready.textContent = localLobbyReady ? 'READY ✓' : 'READY';
  ready.classList.toggle('primary', localLobbyReady);
  ready.disabled = !localMember?.connected || (snapshot?.phase ?? 'waiting') !== 'waiting' || !lobbyArenaSynchronized;
  const start = element<HTMLButtonElement>('#lobby-start');
  start.hidden = network.role !== 'host';
  // HF-323: disable START control while a guest admission is in flight or connection is pending
  const pendingGuest = hostHasPendingGuestConnection();
  start.disabled = network.role !== 'host' || !snapshot || !lobbyArenaSynchronized || !canHostCommitStart(snapshot, pendingGuest);
  const resetLobby = element<HTMLButtonElement>('#lobby-reset');
  resetLobby.disabled = network.role !== 'host';
  resetLobby.title = network.role === 'host'
    ? 'Close this room and create a fresh code; the old room cannot be reclaimed.'
    : 'Only the host can invalidate the room and create a fresh code.';
  const teamInput = element<HTMLSelectElement>('#team');
  teamInput.disabled = (snapshot?.phase ?? 'waiting') !== 'waiting' || (snapshot?.config.mode ?? privateMatchConfig.mode) === 'ffa';
  // HF-328: the SWAP SIDES affordance must mirror the host's exact legality
  // check (team-prescription.teamSwapRefusal) so a player only sees a live
  // button when the request would be accepted. Before this wiring the button
  // rendered permanently disabled with no listener - an orphan control.
  const swapSides = element<HTMLButtonElement>('#lobby-swap-sides');
  const localConnected = localMember?.connected ?? false;
  const requestedSwapTeam: Team = (localMember?.team ?? player.team) === 0 ? 1 : 0;
  const swapRefusal = localConnected
    ? teamSwapRefusal(members, player.id, requestedSwapTeam, snapshot?.phase ?? 'waiting', snapshot?.config.mode ?? privateMatchConfig.mode)
    : 'not-connected';
  swapSides.disabled = !localConnected || swapRefusal !== null;
  swapSides.title = swapRefusal === null
    ? 'Request to swap sides — the host accepts only swaps that keep teams within one player.'
    : `Swap unavailable (${swapRefusal}).`;
  const roster = element<HTMLElement>('#lobby-roster');
  const renderedMembers = members.map((member) => {
    const ping = member.id === player.id && network.role === 'client' ? localLobbyPingMs : member.pingMs;
    const quality = latencyQuality(ping);
    const role = member.id === snapshot?.hostId || member.id === player.id && network.role === 'host' ? 'HOST' : 'PEER';
    const team = (snapshot?.config.mode ?? privateMatchConfig.mode) === 'ffa' ? 'FFA' : member.team === 0 ? 'AQUA' : 'CORAL';
    const squad = renderSquadRosterBadge(member.squadName, member.squadColor, member.team);
    const handicapControl = member.id === player.id && (snapshot?.phase ?? 'waiting') === 'waiting'
      ? `<label class="lobby-dhv">DHV<select data-lobby-dhv aria-label="Damage Handicap Value">${DHV_VALUES.map((value) => `<option value="${value}"${member.dhv === value ? ' selected' : ''}>${value}</option>`).join('')}</select><small>${dhvLabel(member.dhv)}</small></label>`
      : `<span class="lobby-dhv-badge" title="${dhvLabel(member.dhv)}">DHV ${member.dhv}</span>`;
    return `<div class="lobby-player ${member.connected ? '' : 'disconnected'}"><span><strong>${escapeHtml(member.name)}</strong><small>${role} · ${team} · ${squad}</small></span><b class="latency-${quality}">${ping === null ? '—' : `${Math.round(ping)} ms`}</b>${handicapControl}<em>${member.connected ? member.ready ? 'READY' : 'SETTING UP' : 'REJOINING…'}</em></div>`;
  }).join('');
  // HF-323: show PLAYER JOINING... roster row so host understands the wait
  const pendingRow = pendingGuest
    ? '<div class="lobby-player disconnected"><span><strong>PLAYER JOINING...</strong></span></div>'
    : '';
  roster.innerHTML = (renderedMembers + pendingRow) || '<div class="lobby-player disconnected"><span><strong>CONNECTING…</strong></span></div>';
  const isFfa = (snapshot?.config.mode ?? privateMatchConfig.mode) === 'ffa';
  element<HTMLElement>('#lobby-guidance').textContent = !lobbyArenaSynchronized
    ? lobbyArenaSyncFailed
      ? `Arena sync failed twice for ${arenaSelection(snapshot!.config.arenaId).displayName}. LEAVE the lobby and rejoin - the room stays open.`
      : `Synchronizing ${arenaSelection(snapshot!.config.arenaId).displayName} before ready-up…`
    : snapshot?.phase === 'active'
    ? 'Match active · disconnected players have a 90 second rejoin slot.'
    : snapshot?.phase === 'countdown'
      ? 'Synchronized deployment countdown started.'
      : network.role === 'host'
        ? isFfa
          ? 'Share the invite, then start when every player is ready.'
          : 'Share the invite, balance teams, then start when everyone is ready.'
        : isFfa
          ? 'Ready up. The host controls match start.'
          : 'Choose your squad and ready up. The host controls match start.';
}

/**
 * HF-347 bounded deadline. `lobbyArenaSynchronized` false disables READY under a
 * "Synchronizing..." line with NO time bound: a stalled arena transition wedged the
 * lobby forever, reading as "cant move" the moment the match started without the
 * player. 75 s comfortably exceeds the slowest measured legitimate sync (cold
 * Quality-art streaming ~50 s); one automatic fresh re-selection follows (the
 * admission path documents a fresh selection as the recovery), and a second breach
 * stops pretending: the guidance line names the stall and points at LEAVE, which
 * always works. Runs on its own interval because a stalled transition also stalls
 * the event-driven lobby re-renders - a watchdog that only runs when the patient
 * is healthy diagnoses nothing.
 */
const LOBBY_ARENA_SYNC_DEADLINE_MS = 75_000;
let lobbyArenaSyncPendingSince: number | null = null;
let lobbyArenaSyncPendingArenaId: string | null = null;
let lobbyArenaSyncRetryUsed = false;
let lobbyArenaSyncFailed = false;

function trackLobbyArenaSyncDeadline(synchronized: boolean, targetArenaId: string | null): void {
  if (synchronized || !targetArenaId) {
    lobbyArenaSyncPendingSince = null;
    lobbyArenaSyncPendingArenaId = null;
    lobbyArenaSyncRetryUsed = false;
    lobbyArenaSyncFailed = false;
    return;
  }
  if (lobbyArenaSyncPendingArenaId !== targetArenaId) {
    lobbyArenaSyncPendingArenaId = targetArenaId;
    lobbyArenaSyncPendingSince = performance.now();
    lobbyArenaSyncRetryUsed = false;
    lobbyArenaSyncFailed = false;
  }
}

window.setInterval(() => {
  if (lobbyArenaSyncPendingSince === null || lobbyArenaSyncFailed) return;
  if (!privateLobbySnapshot || gameStarted) return;
  if (performance.now() - lobbyArenaSyncPendingSince < LOBBY_ARENA_SYNC_DEADLINE_MS) return;
  const arenaId = lobbyArenaSyncPendingArenaId;
  if (!arenaId) return;
  if (!lobbyArenaSyncRetryUsed) {
    lobbyArenaSyncRetryUsed = true;
    lobbyArenaSyncPendingSince = performance.now();
    addFeed('ARENA SYNC STALLED - RETRYING', 'gold');
    void activateArenaSelection(arenaId as ArenaId, true);
    return;
  }
  lobbyArenaSyncFailed = true;
  const guidance = document.querySelector<HTMLElement>('#lobby-guidance');
  if (guidance) {
    guidance.textContent = `Arena sync failed twice for ${arenaSelection(arenaId as ArenaId).displayName}. LEAVE the lobby and rejoin - the room stays open.`;
  }
  addFeed('ARENA SYNC FAILED - LEAVE AND REJOIN', 'gold');
}, 5_000);

