  const staged = lastLiveGraphicsApply?.staged ?? [];
  setStatus(staged.length > 0
    ? `GRAPHICS SAVED · live values applied · ${staged.join(', ')} staged for renderer reconstruction.`
    : 'GRAPHICS SAVED · all selected values are live.');
